'Custom_SMS_Payload_Hint' => 'حدّد حقول جسم الطلب. استخدم {phone} و{message} و{sender} كعناصر نائبة؛ وسيتم استبدالها عند الإرسال.',
'Custom_SMS_Guide_Title' => 'طريقة الإعداد',
'Custom_SMS_Guide_Intro' => 'يمكن ربط أي مزوّد SMS يوفّر واجهة HTTP API. افتح وثائق API الخاصة بمزوّدك، وانسخ نقطة النهاية والطريقة وأسماء الحقول، ثم اربطها أدناه باستخدام العناصر النائبة.',
'Custom_SMS_Guide_Placeholder_Phone' => 'رقم هاتف المستلم',
'Custom_SMS_Guide_Placeholder_Message' => 'نص الرسالة SMS',
'Custom_SMS_Guide_Placeholder_Sender' => 'معرّف المرسل المُدخل أعلاه',
'Custom_SMS_Guide_Api_Url' => 'رابط نقطة النهاية الكامل من وثائق مزوّدك، مثل https://api.provider.com/sms/send. يُسمح أيضًا باستخدام العناصر النائبة مباشرة في الرابط، مثل ...?to={phone}&text={message}.',
'Custom_SMS_Guide_Method' => 'POST هي الأكثر شيوعًا. اختر GET فقط إذا كان مزوّدك يتوقع كل شيء في الرابط — حيث تُرسل حقول الحمولة حينها كمعاملات استعلام.',
'Custom_SMS_Guide_Content_Type' => '"json" يرسل الحمولة كجسم JSON (application/json). "form" يرسلها كنموذج HTML تقليدي (application/x-www-form-urlencoded). تحقّق مما يتوقعه مزوّدك؛ ويتم تجاهله مع GET.',
'Custom_SMS_Guide_Sender' => 'معرّف المرسل المعتمد أو رقم هاتف الإرسال. يملأ فقط العنصر النائب {sender} — ولكي يُرسل يجب استخدامه في الحمولة أو الترويسات أو الرابط.',
'Custom_SMS_Guide_Success_Keyword' => 'اختياري ولكن يُنصح به. بعض المزوّدين يردّون بـ "200 OK" حتى عند فشل الإرسال. أدخل كلمة أو جزءًا يظهر فقط في الاستجابة الناجحة (مثل success). إذا لم تحتوِ الاستجابة عليه، تُعتبر الرسالة فاشلة.',
'Custom_SMS_Guide_Headers' => 'ترويسات المصادقة التي يتطلبها مزوّدك، مثل Authorization = Bearer YOUR_API_KEY أو Api-Key = YOUR_API_KEY. لا تُضف Content-Type — فهو يُعيَّن تلقائيًا.',
'Custom_SMS_Guide_Payload' => 'حقول جسم الطلب، بنفس الأسماء الواردة في وثائق مزوّدك تمامًا. استخدم العناصر النائبة كقيم، مثل to = {phone} وmessage = {message} وfrom = {sender}.',
'Custom_SMS_Guide_Example' => 'مثال كامل',
'Custom_SMS_Guide_Default_Note' => 'بعد الحفظ، اختر "custom" كبوابة SMS الافتراضية أعلى هذه الصفحة ثم أرسل — وإلا ستستمر رسائل SMS في استخدام البوابة المحددة سابقًا.',
