'OfflinePayments' => 'المدفوعات خارج النظام',
'OfflinePaymentsIntro' => 'هنا تجد كل ما يُدفع خارج النظام: الدفع عند الاستلام، والمحفظة المتنقلة، وGCash، والتحويل البنكي، والدفع نقدًا عند الاستلام من الفرع. تبقى هذه الطلبات بانتظار الدفع حتى تحددها كمدفوعة. يطلب GCash والتحويل البنكي من العميل لقطة شاشة ورقمًا مرجعيًا والمبلغ، وتوافق عليها أنت من صفحة الطلب.',
