'Ord_Guide_Lifecycle_Title' => 'حالة الطلب',
'Ord_Guide_MarkPaid_Note' => 'تظل حالة الدفع المعروضة هنا تسجّل الخيار الذي اختاره العميل عند الدفع ولا تتغيّر. عملية البيع هي السجل المحاسبي، وهي التي تغذّي تقارير المدفوعات والأرباح. استخدم «عرض المدفوعات» في عملية البيع لمراجعة ما أدخلته أو تعديله.',
