'Ord_Guide_Payment_Failed' => 'رفضت بوابة الدفع العملية أو تخلّى العميل عنها. يُلغى الطلب تلقائيًا.',
'Ord_Guide_Payment_Intro' => 'يسجّل هذا العمود طريقة الدفع التي اختارها العميل عند إتمام الطلب. يحددها المتجر ولا يمكن تعديلها من هذه الصفحة — أما المبلغ نفسه فيُتتبَّع في عملية البيع التي يُنشئها تأكيد الطلب.',
'Ord_Guide_Payment_Paid' => 'دفع العميل مسبقًا عبر الإنترنت من خلال بوابة دفع. تأكيد الطلب يُنشئ عملية بيع مدفوعة ويسجّل الدفعة تلقائيًا — لا حاجة لأي إجراء آخر.',
