'Cr_Guide_T_Booking' => 'حجز الطلبات',
'Cr_Guide_B_Booking' => 'يملأ إرسال إلى شركة الشحن النموذج من البيع: المستلم، والعنوان، والمبلغ المتبقي كدفع عند الاستلام، ووزن المنتجات. تعرض شركات الشحن التي لديها قوائم مدن خاصة بها أداة اختيار، ويُحفظ اختيارك لتلك المدينة. توفر المنصات المجمِّعة وDHL وFedEx وUPS وLalamove خيار مقارنة الأسعار: اختر سعرًا وسيشتريه زر حجز. يمكن حجز عدة مبيعات دفعة واحدة من قائمة المبيعات.',
'Cr_Guide_T_Cod' => 'الدفع عند الاستلام',
'Cr_Guide_B_Cod' => 'ينتقل طرد الدفع عند الاستلام من لم يُحصَّل إلى حصّلته شركة الشحن (عند التسليم) ثم إلى حُوِّل إليك. شركات الشحن التي تُبلغ عن التحويلات تنقل الخطوة الأخيرة بنفسها؛ أما البقية فاستخدم تحديث الدفع عند الاستلام. عند اختيار حساب في إعدادات شركات الشحن، يُسجَّل التحويل كدفعة على البيع. يمكن حفظ رسوم شركة الشحن كمصروف بمجرد انتهاء الطرد.',
'Cr_Guide_T_Returns' => 'الطرود المرتجعة',
'Cr_Guide_B_Returns' => 'افتراضيًا، ينتظر الطرد المرتجع في شحنات شركات الشحن ضمن مرتجعات للمراجعة. تنشئ إعادة إلى المخزون مرتجع بيع للطلب بالكامل وتعيد الأصناف إلى المخزون؛ أما تجاهل فلا يعيد شيئًا، وهو مخصص للطرود التالفة أو المفقودة. ويمكن لإعدادات شركات الشحن الإعادة إلى المخزون تلقائيًا بدلًا من ذلك.',
'Cr_Guide_T_Customers' => 'رسائل الزبائن وصفحة التتبع',
'Cr_Guide_B_Customers' => 'ترسل إشعارات الزبائن في إعدادات شركات الشحن رسائل SMS أو بريدًا إلكترونيًا أو WhatsApp عند الحالات التي تحددها، مرة واحدة لكل طرد، وبنصك الخاص. تتيح صفحة التتبع في متجرك الإلكتروني للزبائن متابعة الطرد برقم التتبع، أو برقم الطلب والهاتف. ويحصل الزبائن الذين يُرجعون الطرود كثيرًا على شارة مخاطر الإرجاع عند الحجز.',
'Cr_Guide_T_Labels' => 'الملصقات',
'Cr_Guide_B_Labels' => 'تعطي طباعة الملصق ملصق شركة الشحن الخاص عندما تصدره (ملف PDF أو رابط أو صورة)، وإلا فملصق Stocky يحتوي على باركود التتبع والمبلغ المطلوب تحصيله. اسمح بالنوافذ المنبثقة لهذا الموقع للطباعة. تعطي DHL وFedEx وUPS ملصقها مرة واحدة فقط عند الحجز، ويحتفظ به Stocky لإعادة الطباعة.',
'Cr_Guide_T_Faq' => 'استكشاف الأخطاء وإصلاحها',
'Cr_Guide_Q_Test' => 'فشل اختبار الاتصال',
'Cr_Guide_A_Test' => 'مفاتيح الوضع التجريبي تُستخدم مع الوضع التجريبي، والمفاتيح المباشرة مع الوضع المباشر؛ وهي مختلفة. افتح سجلات شركات الشحن واقرأ رد شركة الشحن لمعرفة السبب بالضبط.',
'Cr_Guide_Q_City' => 'شركة الشحن ترفض المدينة أو العنوان',
'Cr_Guide_A_City' => 'اختر المدينة من قائمة مدن شركة الشحن في نموذج الحجز؛ فشركات الشحن لا تقبل إلا أسماءها الخاصة. كما تحتاج شركات الشحن التي تعمل بالعناوين البريدية إلى الولاية والرمز البريدي ورمز الدولة المكون من حرفين.',
'Cr_Guide_Q_Webhook' => 'الحالات لا تتغير تلقائيًا',
'Cr_Guide_A_Webhook' => 'بالنسبة لشركات الشحن التي ترسل التحديثات، تحقق من تسجيل رابط Webhook لدى شركة الشحن: تعرض سجلات شركات الشحن كل تحديث مُستلَم، أو سبب رفضه (مثل سر خاطئ). أما شركات الشحن الأخرى فيتم فحصها وفق الجدول في إعدادات شركات الشحن، ويطلب زر فحص الحالة الآن ذلك فورًا.',
'Cr_Guide_Q_Stuck' => 'تظهر في الشحنة رسالة خطأ في فحص الحالة',
'Cr_Guide_A_Stuck' => 'رفضت شركة الشحن عمليات الفحص الأخيرة؛ والسبب موجود في الشحنة وفي سجلات شركات الشحن. بعد تكرار الفشل لا تُفحص الشحنة تلقائيًا بعد ذلك: أصلح السبب، ثم استخدم فحص الحالة الآن.',
'Cr_Guide_Q_Label' => 'لا يُفتح شيء عند طباعة ملصق',
'Cr_Guide_A_Label' => 'حظر متصفحك النافذة المنبثقة. اسمح بالنوافذ المنبثقة لهذا الموقع وحاول مرة أخرى.',
'Cr_Guide_Q_Cod' => 'لم يُسجَّل تحويل الدفع عند الاستلام على البيع',
'Cr_Guide_A_Cod' => 'في إعدادات شركات الشحن، يتطلب الدفع عند الاستلام تشغيل المفتاح واختيار حساب. بدون حساب، تُعلَّم التحويلات فقط كمحوَّلة.',
