'Restrict_Master_Data_By_Warehouse_Help' => 'عند التفعيل، لا يرى المستخدم المعيَّن لمستودعات محددة إلا المنتجات والزبائن والموردين والعلامات التجارية والفئات المرتبطة بتلك المستودعات. تبقى السجلات غير المستخدمة في أي مكان مرئية، لذا لا تُخفى السجلات المنشأة حديثًا أبدًا. المبيعات والمشتريات والمرتجعات مقيدة دائمًا ولا تتأثر بهذا المفتاح.',
