'Restrict_Products_By_Warehouse_Help' => 'يحصل كل منتج على مستودع أساسي — الفرع الذي أُنشئ من أجله. عند التفعيل، لا يرى المستخدم المعيَّن لمستودعات محددة ولا يبيع ولا يعدّل إلا المنتجات التي يكون مستودعها الأساسي من مستودعاته، إضافة إلى المنتجات التي لها مخزون فعلي في أحد مستودعاته (محوَّل إليها أو مشترى فيها). المستخدمون المسموح لهم بالوصول إلى جميع المستودعات يرون كل شيء دائمًا.',
'Virtual_Combo_Stock' => 'مخزون المجموعة الافتراضي',
'Virtual_Combo_Stock_Help' => 'عند التفعيل، لا يكون للمنتج المجمع مخزون خاص به: فتوفره هو عدد المجموعات التي لا تزال المنتجات المكونة له قادرة على تكوينها، وبيع المجموعة يخصم المخزون من المكونات. عند التعطيل، يتم تجميع المجموعات في المخزون عبر تعديل أولًا.',
'Virtual_Combo_Stock_Warning' => 'يُفضَّل اختياره قبل بيع المجموعات. بعد بيع المجموعات أو إرجاعها، يؤدي التبديل إلى أن تعكس عمليات التعديل والحذف والإرجاع اللاحقة لتلك المستندات مخزونها بطريقة خاطئة.',
'Virtual_Combo_Stock_Confirm_On_Title' => 'تفعيل مخزون المجموعة الافتراضي؟',
'Virtual_Combo_Stock_Confirm_On_Body' => 'ستُباع المجموعات مباشرة من منتجاتها المكونة، ولن يُستخدم مخزونها الخاص بعد الآن.',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'تعطيل مخزون المجموعة الافتراضي؟',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'ستعود المنتجات المجمعة إلى مخزونها الخاص، والذي يجب تجميعه من المكونات عبر تعديل قبل أن يمكن بيعها.',
'Home_Warehouse' => 'المستودع الأساسي',
'Home_Warehouse_Hint' => 'الفرع الذي ينتمي إليه هذا المنتج. لن يراه المستخدمون المقيّدون بمستودعات أخرى ما لم يتم تحويل مخزون إليهم.',
'Home_Warehouse_Required' => 'اختر المستودع الذي ينتمي إليه هذا المنتج.',
'Combo_products_required' => 'أضف منتجًا واحدًا على الأقل إلى المجموعة.',
'Customer_Performance_Help' => 'عرض درجة أداء وتقييم في صفحة الزبون، مبنيين على الانتظام في الدفع ومدى حداثة آخر شراء ومعدل المرتجعات.',
'Product_Supplier' => 'المورد في المنتجات',
'Product_Supplier_Help' => 'يضيف حقل مورد افتراضي إلى نموذج المنتج، ويعرضه كعمود في قائمة المنتجات، ويتيح لك تصفية المنتجات حسب المورد لإعداد قائمة إعادة الطلب.',
'Default_Supplier_Hint' => 'المورد الذي تعيد طلب هذا المنتج منه عادةً. صفِّ قائمة المنتجات حسب المورد لرؤية كل ما يجب طلبه منه.',
