'Recon_Intro' => 'يقارن الرصيد التشغيلي لكل حساب نقدي وبنكي برصيد دفتر الأستاذ العام لحساب الدفتر المرتبط به. هذه الصفحة للقراءة فقط: لا تغيّر أيًّا من الرصيدين أبدًا.',
