'Tg_Guide_How_Sent' => 'كيف تُرسل الرسائل',
'Tg_Guide_A_Title' => 'فورًا — لا شيء لتثبيته',
'Tg_Guide_A_Body' => 'أي عملية بيع أو شراء أو دفعة أو مصروف تُحفظ في Stocky — في نقطة البيع أو في لوحة الإدارة — تُرسل إلى Telegram {rightAfter} حفظها، ضمن الطلب نفسه. لا حاجة لمهمة Cron ولا لعامل طابور، ولا ينتظر الكاشير Telegram أبدًا: فعملية البيع تكون قد اكتملت عند إرسال الرسالة.',
'Tg_Guide_Right_After' => 'مباشرة بعد',
'Tg_Guide_B_Title' => 'مهمة Cron — لإعادة المحاولة والأحداث في الخلفية',
'Tg_Guide_B_Body' => 'نوعان من الرسائل ينتظران في طابور Telegram الخاص بدلًا من ذلك: إرسال فشل (تعذّر الوصول إلى Telegram للحظة)، وتُعاد محاولته حتى ثلاث مرات إضافية خلال الدقائق التالية؛ والأحداث التي تنشأ خارج لوحة الإدارة — الطلبات المستوردة من WooCommerce أو Shopify، وأوامر artisan. مهمة Cron هذه ترسلها، ولا شيء غيرها:',
'Tg_Guide_B_Note' => 'كل دقيقة هو الإعداد الصحيح: التشغيل الذي لا يجد شيئًا منتظرًا ينتهي فورًا. على cPanel يوضع هذا في {cronJobs} — استخدم المسار الكامل لـ PHP 8.2+ إذا كان {php} أقدم. على Windows، استخدم Task Scheduler مع البرنامج {php2}، والوسائط {args}، وبدء التشغيل في {path}.',
