'Jumia_Orders_Desc' => 'يستورد طلبات السوق كمبيعات (بمراجع مثل {ref})، مطابقةً لمنتجاتك عبر Seller SKU. يتم تخطي الطلبات المستوردة سابقًا والملغاة، لذا فإن السحب المنتظم آمن. تُعلَّم المدفوعات كمدفوعة للطلبات المُسلَّمة فقط (يغلب الدفع عند الاستلام على Jumia).',
