'Jumia_Guide_2' => 'أدخل رابط API لبلدك (مثل {ng} لنيجيريا، {ke} لكينيا، {eg} لمصر)، والبريد الإلكتروني لحساب Seller Center، والمفتاح — ثم شغّل {test}.',
'Jumia_Guide_3' => 'تأكد من أن {sellerSku} لكل قائمة في Jumia يساوي كود المنتج في Stocky — فهو المعرّف المستخدم لإرسال المخزون ومطابقة الطلبات معًا.',
'Jumia_Guide_4' => 'أرسل الأسعار والمخزون بعد تغييرات المخزون؛ واسحب الطلبات بانتظام (لا توجد Webhooks في هذه الـ API لدى Jumia).',
'Jumia_Guide_5' => 'يبقى إنشاء القوائم الجديدة في Seller Center — إذ تتطلب Jumia سمات خاصة بكل فئة ومراجعة للصور لا تُحسن التعامل معها إلا بوابتها.',
