'Mc_Push_Desc' => 'يضيف أو يحدّث كل زبون لديه عنوان بريد إلكتروني في الجمهور المحدد (مع الاسم والهاتف). يحتفظ الأعضاء الحاليون بحالة اشتراكهم — لا يُعاد اشتراك أي شخص ألغى اشتراكه. يُستبعد الزبائن الذين ليس لديهم بريد إلكتروني.',
