'Presta_Orders_Desc' => 'يستورد طلبات المتجر كمبيعات (بمراجع مثل {ref})، الأحدث أولًا. يتم تخطي الطلبات المستوردة سابقًا والملغاة، لذا فإن السحب المنتظم آمن. لا يدعم PrestaShop الـ Webhooks — شغّل هذا بعد فترات الذروة.',
