'Fbr_Guide_What_Title' => 'ما هي الفوترة الرقمية FBR؟',
'Fbr_Guide_What_Body' => 'بموجب القرار SRO 69(I)/2025، يُلزم المجلس الاتحادي للإيرادات (باكستان) الشركات المتكاملة بالإبلاغ عن فواتير المبيعات إلكترونيًا وفي الوقت الفعلي عبر واجهة PRAL للفوترة الرقمية (DI) API. تحصل كل عملية بيع مقبولة على رقم فاتورة رسمي من FBR، ويجب أن تعرض الإيصالات هذا الرقم مع رمز QR للتحقق.',
'Fbr_Guide_Steps_Title' => 'خطوات التشغيل الفعلي',
'Fbr_Guide_Step_1' => 'سجّل في بوابة FBR IRIS للفوترة الإلكترونية واحصل على رمز أمان لبيئة {sandbox}.',
'Fbr_Guide_Step_2' => 'اضبط ملف البائع في تبويب الإعدادات (NTN/CNIC، اسم النشاط التجاري، المقاطعة، العنوان)، والصق الرمز، وفعّل التكامل مع ضبط البيئة على {sandbox}.',
'Fbr_Guide_Step_3' => 'أجرِ مبيعات تجريبية تغطي السيناريو (السيناريوهات) المخصصة لك من FBR (اختر السيناريو في حقل سيناريو بيئة الاختبار). تحقق من تبويب المستندات للتأكد من أنها تعود بحالة {valid}.',
'Fbr_Guide_Step_4' => 'بعد موافقة FBR على اختباراتك في بيئة الاختبار، احصل على رمز {production} من البوابة، والصقه هنا، وبدّل البيئة إلى {production}.',
'Fbr_Guide_Step_5' => 'تعرض الإيصالات تلقائيًا رقم فاتورة FBR ورمز QR بمجرد قبول عملية البيع — دون أي خطوات إضافية في نقطة البيع.',
