'Woo_WordPress_App_Password' => 'كلمة مرور تطبيق WordPress',
'Woo_Automatic_Sync' => 'المزامنة التلقائية',
'Woo_Auto_Sync_Intro' => 'إرسال التغييرات التي تُجرى في Stocky إلى WooCommerce فور حدوثها، دون فتح هذه الصفحة. يتم كل إرسال مباشرة بعد حفظ الإجراء، فلا ينتظر الكاشير WooCommerce أبدًا. تظهر النتائج في تبويب السجلات.',
'Woo_Auto_Sync_Products_Help' => 'يُرسَل المنتج الذي يُنشأ أو يُعدَّل أو يُنسخ في Stocky إلى WooCommerce (التفاصيل، السعر، المتغيرات، الصور، المخزون). لا تُرسَل عمليات الاستيراد المجمّعة؛ بعد الاستيراد استخدم مزامنة — نقطة البيع ← WooCommerce في تبويب المنتجات.',
'Woo_Auto_Sync_Stock_Help' => 'أي حركة مخزون (بيع في نقطة البيع، بيع، مرتجع، شراء، تعديل، تحويل) تُحدّث كمية المنتجات المعنية على WooCommerce. تُحدَّث فقط المنتجات المربوطة مسبقًا بـ WooCommerce.',
'Woo_Sync_Tuning' => 'ضبط المزامنة',
'Woo_Sync_Tuning_Intro' => 'تناسب القيم الافتراضية معظم المتاجر. غيّرها فقط إذا كانت المزامنة بطيئة أو تنتهي مهلتها على الاستضافة لديك. كل قيمة محصورة ضمن نطاق آمن، ومسح الحقل يعيد قيمته الافتراضية.',
'Woo_Sync_Guide' => 'دليل مزامنة WooCommerce',
'Woo_Guide_Getting_Keys' => 'الحصول على مفاتيح API',
'Woo_Guide_Keys_1' => 'في WooCommerce: WooCommerce ← الإعدادات ← متقدم ← REST API.',
'Woo_Guide_Keys_2' => 'أضف مفتاحًا، واختر قراءة/كتابة، ثم انسخ Consumer key وConsumer secret.',
'Woo_Guide_Keys_3' => 'رابط المتجر: عنوان URL لموقعك دون شرطة مائلة في النهاية (مثال: {example}).',
'Woo_Guide_WP_Title' => 'اسم مستخدم WP وكلمة مرور التطبيق (اختياري)',
'Woo_Guide_WP_Intro' => 'تُستخدم هذه الحقول لصور المنتجات فقط. تتولى WooCommerce API (رابط المتجر + Consumer key/secret) مزامنة المنتجات والمخزون والفئات والعلامات التجارية والزبائن والطلبات؛ بينما تتولى WordPress REST API مكتبة الوسائط (البحث عن الصور ورفعها).',
'Woo_Guide_WP_1' => 'عند مزامنة المنتجات أو المخزون، يمكن لـ Stocky إرفاق صور المنتجات: يبحث أولًا في مكتبة وسائط WordPress عن صورة موجودة حسب اسم الملف؛ وإن لم يجدها، يرفع الصورة عبر WordPress API.',
'Woo_Guide_WP_2' => 'استخدم مستخدم WordPress يمكنه إدارة الوسائط (مثل المسؤول). أنشئ كلمة مرور تطبيق في WordPress: المستخدمون ← الملف الشخصي (أو مستخدمك) ← كلمات مرور التطبيقات — أضف واحدة جديدة والصقها هنا.',
'Woo_Guide_WP_3' => 'إذا تركت هذه الحقول فارغة، تظل المزامنة تعمل لجميع البيانات (المنتجات، المخزون، الفئات، العلامات التجارية، الزبائن، الطلبات)؛ ويتم تخطي إرفاق صور المنتجات (البحث/الرفع) فقط.',
'Woo_Guide_How_To_Enable' => 'طريقة التفعيل',
'Woo_Guide_Enable_1' => 'أدخل رابط المتجر وConsumer key وConsumer secret أعلاه، ثم انقر على حفظ.',
'Woo_Guide_Enable_2' => 'استخدم اختبار الاتصال للتحقق من بيانات الاعتماد.',
'Woo_Guide_Enable_3' => 'استخدم المزامنة اليدوية من أي تبويب عندما تحتاج إلى المزامنة.',
'Woo_Guide_Enable_4' => 'فعّل المزامنة التلقائية أعلاه لإرسال المنتجات الجديدة والمعدّلة وكل تغيير في المخزون إلى WooCommerce فور حدوثه.',
'Woo_Guide_Manual_Sync' => 'المزامنة اليدوية (عند الطلب)',
'Woo_Guide_Manual_1' => 'تعمل المزامنة في الاتجاهين: Stocky → WooCommerce وWooCommerce → Stocky.',
'Woo_Guide_Manual_2' => 'المزامنة اليدوية متاحة في جميع تبويبات WooCommerce (المنتجات، المخزون، إلخ)؛ استخدم إجراءات المزامنة في كل تبويب لتشغيل المزامنة عند الطلب.',
'Woo_Guide_Auto_1' => 'المنتجات: عند التفعيل، يُرسَل المنتج الذي تنشئه أو تعدّله أو تنسخه في Stocky إلى WooCommerce مباشرة بعد حفظه، يليه مخزونه.',
'Woo_Guide_Auto_2' => 'المخزون: عند التفعيل، يُحدّث كل تغيير في المخزون (بيع في نقطة البيع، بيع، مرتجع، شراء، تعديل، تحويل) الكمية على WooCommerce. تُحدَّث فقط المنتجات المربوطة مسبقًا بـ WooCommerce.',
'Woo_Guide_Auto_3' => 'ترسل المزامنة التلقائية التغييرات من Stocky إلى WooCommerce فقط. أما جلب البيانات من WooCommerce إلى Stocky (الطلبات، الزبائن، المنتجات) فيتم دائمًا عبر الأزرار في تبويبات الطلبات والزبائن والمنتجات.',
'Woo_Guide_Auto_4' => 'لا تُرسَل عمليات استيراد المنتجات المجمّعة تلقائيًا. بعد الاستيراد، استخدم مزامنة — نقطة البيع ← WooCommerce في تبويب المنتجات.',
'Woo_Guide_Auto_5' => 'يُسجَّل كل إرسال تلقائي في تبويب السجلات، لتتمكن من التحقق مما أُرسل واكتشاف الأخطاء.',
'Woo_Guide_First_Setup' => 'الإعداد الأول',
'Woo_Guide_First_1' => 'شغّل هذه الخطوات مرة واحدة وبهذا الترتيب لربط الكتالوج الحالي: مزامنة — نقطة البيع ← WooCommerce في تبويب الفئات، ثم تبويب العلامة التجارية، ثم تبويب المنتجات، وأخيرًا مزامنة المخزون في تبويب المخزون. بعد ذلك، فعّل المزامنة التلقائية أعلاه لإبقاء WooCommerce محدّثًا.',
'Woo_Guide_First_2' => 'تعمل مزامنات المنتجات والمخزون الكبيرة على دفعات صغيرة وتعرض تقدمها في التبويب. أبقِ الصفحة مفتوحة حتى تنتهي المزامنة؛ ويمكنك إيقافها في أي وقت.',
'Woo_Guide_First_3' => 'إذا توقفت المزامنة عن التقدم لعدة دقائق، تحقق من تبويب السجلات، ثم تواصل مع الدعم.',
'Woo_Guide_Notes_1' => 'تغيير رابط المتجر أو مفاتيح API يعيد تعيين الربط (المنتجات، الفئات، العلامات التجارية، الزبائن)؛ وستتم مزامنة العناصر مجددًا مع المتجر (الجديد).',
'Woo_Guide_Notes_2' => 'حافظ على تطابق رموز SKU بين Stocky وWooCommerce لتجنب تكرار المنتجات ولإعادة الربط بأمان.',
