'Pg_Stripe_Shared_Notice' => 'مفاتيح Stripe مشتركة على مستوى النظام بالكامل.',
'Pg_Store_Feature_Not_In_Plan' => 'بوابات المتجر الإلكتروني وطرق الدفع خارج النظام جزء من ميزة طلبات المتجر الإلكتروني، وهي غير مضمّنة في خطتك الحالية.',
'Pg_Intro_Title' => 'كل بوابة هنا تُعرض عند إتمام الشراء في المتجر الإلكتروني بمجرد حفظ بيانات اعتمادها وتفعيل مفتاحها.',
'Pg_Intro_Desc' => 'لكل تبويب مفتاح تشغيل/إيقاف خاص به، يُحفظ لحظة تبديله: تعطيل البوابة يُبقي بيانات اعتمادها كما هي، ويتوقف إتمام الشراء ببساطة عن عرضها. مفاتيح Stripe مشتركة على المستوى العام (لوحة الإدارة والمتجر الإلكتروني يستخدمان تكامل Stripe نفسه). يتضمن تبويب المدفوعات خارج النظام الدفع عند الاستلام والأموال عبر الهاتف المحمول، والتي تُدفع خارج النظام.',
