'Pg_Label_Stripe_Secret' => 'المفتاح السري لـ STRIPE',
'Pg_Card_Payments_Off' => 'مدفوعات البطاقات معطّلة',
'Pg_Card_Keys_Kept' => 'مفاتيحك محفوظة — يتوقف إتمام الشراء في المتجر الإلكتروني ببساطة عن عرض خيار البطاقة حتى تعيد تفعيله.',
'Pg_No_Stripe_Key' => 'لا يوجد مفتاح Stripe محفوظ',
