'Pg_Label_Razorpay_Key_Id' => 'معرّف مفتاح RAZORPAY',
'Pg_Label_Razorpay_Key_Secret' => 'المفتاح السري لـ RAZORPAY',
'Pg_Razorpay_Help' => 'يستخدم Razorpay Checkout في واجهة المتجر (البطاقات، UPI، الخدمات المصرفية عبر الإنترنت، المحافظ). يُحدَّد وضع الاختبار أو الإنتاج حسب زوج المفاتيح (rzp_test_/rzp_live_) — لا يوجد مفتاح منفصل لبيئة الاختبار. يعرض إتمام الشراء Razorpay بمجرد حفظ المفتاحين.',
