'Pg_Label_Bkash_Password' => 'كلمة مرور BKASH',
'Pg_Bkash_Sandbox_Help' => 'عند التفعيل يُستخدم tokenized.sandbox.bka.sh مع بيانات اعتماد بيئة الاختبار؛ عطّله لتحصيل المبالغ من حسابات bKash حقيقية على tokenized.pay.bka.sh.',
'Pg_Bkash_Help' => 'يستخدم bKash Tokenized Checkout (بيانات اعتماد التاجر من بوابة تجار bKash). التحصيل بعملة BDT. يعرض إتمام الشراء bKash بمجرد حفظ بيانات الاعتماد الأربع جميعها.',
'Pg_Label_Sslcommerz_Store_Id' => 'معرّف متجر SSLCOMMERZ',
'Pg_Label_Sslcommerz_Store_Password' => 'كلمة مرور متجر SSLCOMMERZ',
'Pg_Sslcommerz_Sandbox_Help' => 'عند التفعيل يُستخدم sandbox.sslcommerz.com مع بيانات اعتماد بيئة الاختبار؛ عطّله لتحصيل المبالغ من زبائن حقيقيين على securepay.sslcommerz.com.',
'Pg_Sslcommerz_Help' => 'صفحة دفع مستضافة تغطي البطاقات والخدمات المصرفية عبر الهاتف bKash/Nagad/Rocket والخدمات المصرفية عبر الإنترنت في بنغلاديش. التحصيل بعملة BDT.',
