'Pg_Label_Hmac_Secret' => 'سر HMAC',
'Pg_Label_Charge_Currency' => 'عملة التحصيل',
'Pg_Paymob_Currency_Help' => 'يجب أن تطابق عملة حساب Paymob الخاص بك (EGP أو SAR أو AED أو PKR أو OMR) والعملة الأساسية لمتجرك.',
'Pg_Paymob_Help' => 'يستخدم Paymob Unified Checkout (البطاقات والمحافظ والطرق المحلية في مصر والسعودية والإمارات وباكستان وعُمان). تأتي بيانات الاعتماد الخمس كلها من لوحة تحكم Paymob → Settings → Account Info + Payment Integrations.',
'Pg_Paymob_Webhook_Help' => 'يُضبط Webhook تلقائيًا لكل عملية دفع — لا حاجة لأي إعداد في لوحة التحكم. رابط الاستدعاء الاحتياطي للرجوع إليه:',
'Pg_Label_Api_Token' => 'رمز API',
'Pg_Label_Account_Country_Live' => 'بلد الحساب (الإنتاج)',
