'Shp_G_Cred_Dev' => '{app} (أي متجر يُربط الآن) — {path}. امنح صلاحيات Admin API لما يزامنه هذا المتجر، وثبّت التطبيق على المتجر، ثم انسخ {clientId} و {clientSecret} من صفحة إعدادات التطبيق إلى {edit}. يستبدلهما نظام ERP برمز وصول بنفسه ويجدده قبل انتهاء صلاحيته كل 24 ساعة. سر العميل يوقّع الـ Webhooks أيضًا، فلا حاجة لأي شيء آخر. يجب أن يكون التطبيق والمتجر ضمن نفس مؤسسة Shopify.',
'Shp_G_Dev_App' => 'تطبيق Dev Dashboard',
'Shp_G_Cred_Legacy' => '{app} (أُنشئ في لوحة الإدارة قبل 2026) — يستمر في العمل دون تغيير باستخدام {token} ({prefix}) و {secret} كسر توقيع Webhook. وهي ليست نفس قيمة الرمز، والخلط بينهما هو السبب المعتاد لرفض الـ Webhooks.',
'Shp_G_Legacy_App' => 'تطبيق مخصص قديم',
'Shp_G_Api_Secret_Key' => 'مفتاح API السري',
'Shp_G_Stored' => 'محفوظ',
'Shp_G_Missing_Refused' => 'مفقود — سيتم رفض عمليات التسليم',
'Shp_G_Targets' => '{path} مستودع ERP الذي يبيع هذا المتجر من مخزونه، وموقع Shopify الذي يُكتب إليه ذلك المخزون. ترفض مزامنة المخزون واستيراد الطلبات العمل بدونهما.',
'Shp_G_Currently' => 'حاليًا: المستودع {warehouse}، الموقع {location}',
'Shp_G_Not_Set_Lc' => 'غير محدد',
'Shp_G_Ready' => 'جاهز',
'Shp_G_Incomplete' => 'غير مكتمل',
'Shp_G_Manual_Syncs' => 'عمليات المزامنة التي تبدؤها يدويًا',
'Shp_G_Manual_Body' => 'المزامنة التي تبدأ من {centre} تستجيب فورًا وتعمل في الخلفية، على شكل أجزاء قصيرة يكمل كل منها من حيث توقف السابق. لا يُقطع الكتالوج الكبير في منتصفه بسبب طلب ويب انتهت مهلته، وإغلاق الصفحة لا يوقفه.',
'Shp_G_Worker_Managed' => 'منصتك تشغّل العامل (worker) لذلك، فلا حاجة لتثبيت أي شيء.',
'Shp_G_Worker_Cron' => 'العامل (worker) لذلك هو سطر cron إضافي واحد:',
'Shp_G_Cron_Copied' => 'تم نسخ سطر cron',
'Shp_G_Worker_Busy' => 'إذا كان العامل مشغولًا، تتولى صفحة مركز المزامنة المفتوحة إكمال التشغيل بنفسها بعد بضع ثوانٍ، بطلب قصير في كل مرة — لذا تكتمل المزامنة دائمًا وأنت تشاهدها.',
'Shp_G_Pick_How' => 'ثم اختر طريقة بقائه متزامنًا',
'Shp_G_Right_Away' => 'فورًا',
'Shp_G_Stock_Live' => 'المخزون مباشر',
'Shp_G_Stock_Not_Live' => 'المخزون غير مباشر',
'Shp_G_Realtime_Lead' => 'يُرسل كل تغيير لحظة حدوثه، خلال ثوانٍ. هناك نصفان، ولكل منهما مفتاح منفصل: {webhooks} تجلب أحداث المتجر، و {push} يرسل المخزون إلى الخارج.',
'Shp_G_Webhooks_Lc' => 'الـ Webhooks',
'Shp_G_Instant_Push_Lc' => 'الدفع الفوري للمخزون',
'Shp_G_Webhooks_Heading' => 'الـ Webhooks — المتجر ← نظام ERP',
'Shp_G_Webhooks_Body' => 'الطلبات، وتغييرات حالة الطلبات، وتعديلات المنتجات والزبائن والمخزون التي تتم في Shopify. افتح المتجر واضغط {button} في {tab} الخاص به — يمكن الضغط مرتين بأمان. يرسل Shopify إلى:',
'Shp_G_Webhooks_Tab' => 'تبويب Webhooks',
'Shp_G_Webhooks_Note' => 'يجب أن يكون العنوان متاحًا من الإنترنت عبر HTTPS — لن يرسل Shopify إلى {localhost} أو نطاق {test}. تُسجَّل كل عملية تسليم مرة واحدة، فلا يمكن لإعادة محاولات Shopify إنشاء طلب مكرر، ويمكن إعادة تشغيل العملية الفاشلة. تُرفض عمليات التسليم حتى يتم حفظ سر التوقيع من الخطوة 1.',
'Shp_G_Push_Heading' => 'الدفع الفوري للمخزون — نظام ERP ← المتجر',
'Shp_G_People_Miss' => 'هذا هو الإعداد الذي يغفل عنه الناس',
'Shp_G_Push_P1' => 'بيع نقطة البيع {not} يصل إلى Shopify من تلقاء نفسه. إذا تُرك معطّلًا، فلن يعلم المتجر إلا عند خطوة دفع المخزون التالية — وخلال تلك الفترة قد يبيع وحدة سبق أن بعتها عند نقطة البيع.',
'Shp_G_Not' => 'لا',
'Shp_G_Push_P2' => 'فعّل {setting} في {path}. هذا كل الإعداد — بلا عامل (worker) ولا cron. بعدها يرسل كل بيع ومرتجع وتعديل دفعة للمنتجات المعنية فقط، مباشرة بعد حفظ البيع، والبيع المكوّن من عشرين سطرًا يكلّف دفعة واحدة لا عشرين. ولا تنتظرها نقطة البيع أبدًا.',
'Shp_G_This_Store' => 'هذا المتجر:',
'Shp_G_Push_On' => 'مفعّل — يُدفع المخزون عند التغيير',
'Shp_G_Push_Off' => 'معطّل — المخزون وفق الجدول فقط',
'Shp_G_Push_Note' => 'لا يُدفع إلا المنتجات التي لها ربط في Shopify بالفعل، والحركات في مستودع هذا المتجر فقط. العمليات الجماعية — مثل حذف منتج أو إعادة تعيين مستودع — تكتب المخزون دون إطلاق حدث، وهذا أحد أسباب الإبقاء على خطوة المخزون المجدولة أيضًا.',
'Shp_G_Nothing_Else' => 'لا حاجة لتثبيت أي شيء آخر',
'Shp_G_Nothing_Else_Body' => 'لا يحتاج أي من النصفين إلى عامل طوابير (queue worker) أو مدخل cron. يُعالَج الـ Webhook الوارد ضمن الطلب الذي يرسله Shopify؛ ويعمل دفع المخزون الصادر في نفس العملية التي خدمت البيع، {after} إرسال الاستجابة — فلا تنتظر نقطة البيع Shopify أبدًا، والمتجر الذي يتوقف عن الاستجابة يُتخلى عنه بعد عشر ثوانٍ ويُترك لدفع المخزون المجدول التالي.',
'Shp_G_After' => 'بعد',
'Shp_G_Exception' => 'استثناء واحد: تغيير المخزون الذي تجريه مهمة في الخلفية لا توجد استجابة يأتي بعدها، لذا يُوضع في الطابور {queue} بدلًا من ذلك.',
'Shp_G_Queue_Managed' => 'منصتك تشغّل بالفعل عاملًا على ذلك الطابور، لذا تُرسل هذه أيضًا من تلقاء نفسها.',
'Shp_G_Queue_Cron' => 'إذا أردت إرسال هذه بسرعة أيضًا، فقم بتفريغ ذلك الطابور:',
'Shp_G_On_Schedule' => 'وفق جدول',
'Shp_G_On_Lc' => 'مفعّل',
'Shp_G_Off_Lc' => 'معطّل',
'Shp_G_Scheduled_Lead' => 'تتم إعادة فحص كل شيء بشكل دوري، في الاتجاهين. أبطأ من الوقت الفعلي، لكنه ما يدفع المخزون إلى المتاجر التي لا تستخدم الدفع الفوري، وما يلتقط الـ Webhook الفائت، والطريقة الوحيدة لنقل كتالوج كامل.',
'Shp_G_Nothing_To_Install' => 'لا حاجة لتثبيت أي شيء',
'Shp_G_Managed_Body' => 'يتم تشغيل المجدول نيابةً عنك: كل خمس دقائق تسأل منصتك كل متجر عمّا إذا كانت أي خطوة من خطته مستحقة، وتشغّل المستحقة منها. لا يوجد مدخل cron لإضافته ولا خادم لصيانته.',
'Shp_G_Managed_Note' => 'خمس دقائق هي أيضًا أدق دقة يمكن للخطة استخدامها، لأن خمس دقائق هي أقصر فاصل للخطوة. تُحترم الفواصل الأطول بدقة — فالخطوة المضبوطة على 30 دقيقة تُفحص ست مرات وتعمل مرة واحدة.',
'Shp_G_Cron_Entry' => 'مدخل cron',
'Shp_G_Cron_Body' => 'لا يعمل أي شيء مجدول بدونه. سطر واحد، لهذه الوحدة فقط — أضفه بجانب أي شيء آخر اخترت جدولته:',
'Shp_G_Cron_Note' => 'كل خمس دقائق هي أدق دقة يمكن للخطة استخدامها، لأن خمس دقائق هي أقصر فاصل للخطوة. المدخل الأقل تكرارًا يصبح ببساطة الحد الأدنى — مع {every15}، تعمل الخطوة المضبوطة على 5 دقائق كل 15 دقيقة. على Windows استخدم Task Scheduler: البرنامج {php}، والوسائط {args}، ويبدأ في {path}.',
'Shp_G_Switch_On' => 'فعّله، واختر الخطة',
'Shp_G_Plan_Body' => '{path} يحدد المفتاح ما إذا كان يُسمح للمجدول بالعمل أصلًا؛ وتحدد الخطة ما يفعله. كل {step} هي كيان واحد في اتجاه واحد بفاصل زمني خاص — {ex1}، {ex2}. يُستخدم الفاصل الافتراضي لأي خطوة تترك حقلها فارغًا.',
'Shp_G_Step_Lc' => 'خطوة',
'Shp_G_Ex1' => 'الطلبات · Shopify ← ERP كل 15 دقيقة',
'Shp_G_Ex2' => 'المخزون · ERP ← Shopify كل 30 دقيقة',
'Shp_G_Plan_Note' => 'اترك الخطة فارغة وسيسحب المتجر الطلبات ويدفع المخزون بالفاصل الافتراضي، وهو ما تريده معظم المتاجر. الطلبات للسحب فقط: فـ Shopify هو المكان الذي يقدّم فيه الزبون طلبه.',
'Shp_G_Schedule_On' => 'الجدولة مفعّلة',
'Shp_G_Schedule_Off' => 'الجدولة معطّلة — يدوي فقط',
'Shp_G_When_Runs' => 'متى تعمل الخطوة فعليًا',
'Shp_G_When_Body' => 'تكون الخطوة مستحقة عندما تكون آخر مرة {started} فيها نفس الخطوة أقدم من فاصلها، وفقًا لسجل التشغيل. لذا فإن المزامنة التي تبدؤها يدويًا تؤجّل التشغيل التلقائي التالي، والخطوة التي تستمر في الفشل يُعاد تشغيلها وفق فاصلها لا في كل دورة. تعرض نظرة عامة المتجر آخر تشغيل لكل خطوة، وموعدها التالي، وسبب حظرها إن كانت محظورة. شغّل أول دفع للكتالوج يدويًا من مركز المزامنة — كتشغيل تجريبي أولًا — قبل وضعه على جدول.',
'Shp_G_Started_Lc' => 'بدأت',
'Shp_G_Where_Setting' => 'أين يوجد كل إعداد',
'Shp_G_Where_Note' => 'كل هذه الإعدادات موجودة في متجر قائم: {path}، ثم أيقونة القلم (أو {edit} في صفحة المتجر نفسها).',
'Shp_G_Product_Images' => 'صور المنتجات',
'Shp_G_Img1' => 'تُرسل الصور مع المنتج عند {push} — الصورة الرئيسية أولًا، ثم المعرض، ثم صورة لكل متغير له صورته الخاصة، بحد أقصى خمسين.',
'Shp_G_Products_Push' => 'دفع المنتجات',
'Shp_G_Img2' => 'تُرفع صورة المتغير مع المنتج ثم {assigned}، وهذه هي طريقة Shopify في تمثيلها: يشير المتغير إلى إحدى صور المنتج. المتغير الذي يعيد استخدام الصورة الرئيسية لا يرفعها مرتين.',
'Shp_G_Assigned' => 'تُعيَّن لذلك المتغير',
'Shp_G_Img3' => 'الصورة المحفوظة كملف {uploaded} إلى Shopify، ولا تُرسل كرابط، لذا تعمل حتى عندما لا يكون هذا التثبيت متاحًا من الإنترنت. أما الصورة المضافة كرابط ملصق فتُسلَّم إلى Shopify كـ URL، ويجب أن يكون متاحًا للعامة.',
'Shp_G_Uploaded' => 'تُرفع',
'Shp_G_Img4' => 'لا يُعاد إرسالها إلا عند تغيّرها فعليًا — فالدفع الذي يغيّر السعر فقط لا يمس صور المتجر، لأن إرسالها يستبدل المجموعة بأكملها.',
'Shp_G_Img5' => 'إزالة صورة في ERP {not} تحذفها في Shopify. احذفها هناك أيضًا، وإلا سيستمر المتجر في عرضها.',
