'Shp_G_Command_Copied' => 'تم نسخ الأمر',
'Shp_G_Foot' => 'تكتب كل مزامنة إلى {logs}، وتعرض نظرة عامة كل متجر متى عملت كل خطوة آخر مرة، ومتى موعدها التالي، وما الذي يعيقها إن وُجد. هذا هو أول مكان تنظر فيه عندما لا تفعل المزامنة ما توقعته.',
