'Agt_Correct_Confirm' => 'هل تريد إصدار تصحيح برقم جديد لهذا المستند المرفوض؟',
'Agt_Correct' => 'تصحيح',
'Agt_Guide_What_Title' => 'ما الذي تفعله هذه الوحدة',
'Agt_Guide_What_Body' => 'تُصدر كل عملية بيع مكتملة كفاتورة إلكترونية لدى AGT (FR عند الدفع وقت الإنشاء، وإلا FT) وكل مرتجع مستلم كإشعار دائن (NC). يحصل كل مستند على الرقم التالي في سلسلته لدى AGT، ويُوقَّع بمفتاح AGT الخاص بك ويُرسل إلى AGT التي تتحقق منه بعد بضع دقائق. يطبع الإيصال وفاتورة PDF رقم AGT ومقتطف الأمان ورمز QR.',
'Agt_Guide_Steps_Title' => 'الإعداد',
'Agt_Guide_Step_1' => 'انضم إلى الفوترة الإلكترونية (adesão) في Portal do Contribuinte ونزّل مفتاح AGT الخاص بك.',
'Agt_Guide_Step_2' => 'أدخل NIF والمنشأة والمفتاح في تبويب الإعدادات، واختر Homologação، ثم احفظ واستخدم اختبار الاتصال.',
'Agt_Guide_Step_3' => 'في تبويب السلاسل، اطلب سلسلة واحدة لكل نوع مستند تستخدمه (FR، FT، NC) للسنة الحالية.',
'Agt_Guide_Step_4' => 'اربط نسب IVA لديك برموز AGT وحدد رمز الإعفاء للبنود بنسبة 0%.',
'Agt_Guide_Step_5' => 'فعّل الوحدة من إعدادات النظام > الميزات، وأنشئ عملية بيع تجريبية وتحقق من أنها تصبح صالحة في تبويب المستندات.',
'Agt_Guide_Step_6' => 'عندما توافق AGT على انتقالك إلى الإنتاج، انتقل إلى Produção واطلب سلاسل الإنتاج.',
'Agt_Guide_Note_1' => 'لا يمكن تعديل أو حذف عملية بيع أو مرتجع تم إرساله. صحّحه بمرتجع مبيعات (إشعار دائن).',
'Agt_Guide_Note_2' => 'تُصحَّح المستندات المرفوضة من AGT برقم جديد يشير إلى المستند المرفوض؛ ولا يُعاد استخدام الرقم القديم أبدًا.',
'Agt_Guide_Note_3' => 'تُرسل مبيعات نقاط البيع دون اتصال عند مزامنتها. تفرض AGT غرامات على المستندات المرسلة بتأخير يتجاوز 24 ساعة.',
'Agt_Guide_Note_4' => 'لا يمكن أن يحمل البند ضريبة المنتج وضريبة الطلب معًا؛ إذ تتطلب AGT نسبة IVA واحدة لكل بند. يُرسل الشحن كبند معفى.',
'Agt_Guide_Note_5' => 'تُحسب إجماليات AGT لكل بند وقد تختلف عن إجمالي Stocky ببضعة سنتات بسبب التقريب.',
