'Comm_G_T_Credit' => 'أي مندوب يحصل على العمولة؟',
'Comm_G_Credit_Intro' => 'تُنسب كل مبيعة إلى مندوب واحد على الأكثر. يتحقق النظام بهذا الترتيب:',
'Comm_G_Credit_Picked' => 'مندوب المبيعات المختار في المبيعة: حقل مندوب المبيعات في إنشاء مبيعة وتعديل مبيعة، أو زر «البائع» في نقاط البيع. إذا تم تعطيل ذلك المندوب لاحقًا، فلا تحقق المبيعة أي عمولة؛ ولا يُنتقل إلى الخيارات التالية.',
'Comm_G_Credit_Seller' => 'وإلا، المندوب المرتبط بالبائع المختار في نقاط البيع (عند تفعيل مفتاح البائع في نقاط البيع).',
'Comm_G_Credit_Cashier' => 'وإلا، المندوب المرتبط بالمستخدم الذي حفظ المبيعة.',
