'Comm_G_Credit_Note' => 'في نقاط البيع، ترك المندوب على «تلقائي» يستخدم الخيارين 2 و3. الاسم الظاهر بجانب «تلقائي» هو المندوب الذي ستُنسب إليه العمولة.',
'Comm_G_T_When' => 'متى تُحتسب العمولات وتُحدَّث؟',
