'Comm_G_When_Create' => 'إنشاء مبيعة: عند حفظ المبيعة كمكتملة.',
'Comm_G_When_Edit' => 'تعديل مبيعة: حفظ مبيعة مكتملة يعيد حسابها من البداية بإجماليها ومدفوعاتها ومندوبها الحاليين، بما في ذلك العمولات التي أُلغيت.',
'Comm_G_When_Pos' => 'نقاط البيع: عند إكمال مبيعة، بما في ذلك المسودة التي تُكمل لاحقًا.',
'Comm_G_When_Payment' => 'إضافة دفعة إلى مبيعة مكتملة، وهذا ما يتيح لقواعد المبلغ المدفوع احتساب الدفعات المستلمة بعد البيع.',
'Comm_G_When_Cod' => 'الدفع عند الاستلام عبر شركة الشحن: عند تسجيل النقد الذي حصّلته شركة الشحن كدفعة على المبيعة.',
'Comm_G_When_Not_Intro' => 'هذه لا تُنشئ عمولات:',
