'Comm_G_When_Not_Before' => 'المبيعات المحفوظة قبل وجود البرنامج أو القاعدة. لا تُحتسب في الخلفية. فتح هذه المبيعة في تعديل مبيعة وحفظها يحتسبها بالقواعد النشطة في تاريخ المبيعة.',
'Comm_G_When_Not_Import' => 'المبيعات المستوردة من ملف.',
'Comm_G_When_Not_Online' => 'الطلبات المقدمة في المتجر الإلكتروني.',
'Comm_G_T_Statuses' => 'حالات العمولة',
'Comm_G_Meaning' => 'ماذا تعني',
'Comm_G_S_Pending' => 'احتُسبت للتو من مبيعة. لم يراجعها أحد بعد. وافق عليها أو ألغِها في تقرير العمولات.',
'Comm_G_S_Approved' => 'تمت مراجعتها والموافقة عليها. وهي مستحقة للمندوب ويمكن تضمينها في إيصال عمولة. إذا تغيّرت المبيعة وتغيّر المبلغ، تعود إلى حالة معلقة لمراجعة أخرى.',
'Comm_G_S_Paid' => 'مُضمّنة في إيصال عمولة. نهائية: لا تتغير العمولات المدفوعة أبدًا. إذا تغيّرت المبيعة بعد ذلك، يُضاف الفرق كتعديل منفصل.',
'Comm_G_S_Cancelled' => 'لن تُدفع. تبقى ملغاة عند ورود مدفوعات أو مرتجعات لاحقًا. حفظ المبيعة في تعديل مبيعة، أو تحديدها في التقرير والنقر على «إعادة الحساب»، يعيد احتسابها.',
'Comm_G_Field' => 'الحقل',
'Comm_G_T_Programs' => 'برامج العمولات',
'Comm_G_Programs_Body' => 'البرنامج حاوية للقواعد، وعادة يكون برنامجًا واحدًا لكل فترة أو حملة. لا تعمل القاعدة إلا عندما يكون برنامجها نشطًا ويقع تاريخ المبيعة ضمن تواريخ البرنامج. يمكن أن تكون عدة برامج نشطة في الوقت نفسه، وتُطبَّق جميعها.',
'Comm_G_F_Program_Name' => 'أي اسم يساعدك على تمييز البرنامج، مثل «الربع الرابع 2026» أو «الجمعة البيضاء».',
'Comm_G_F_Program_Active' => 'ألغِ تحديده لإيقاف جميع قواعد البرنامج مؤقتًا دفعة واحدة. لا تتأثر العمولات التي أُنشئت مسبقًا.',
'Comm_G_F_Program_From' => 'يتجاهل البرنامج المبيعات المؤرخة قبل هذا اليوم. اتركه فارغًا لعدم تحديد تاريخ بدء.',
'Comm_G_F_Program_To' => 'يتجاهل البرنامج المبيعات المؤرخة بعد هذا اليوم. اتركه فارغًا لبرنامج لا ينتهي.',
'Comm_G_T_Agents' => 'مندوبو المبيعات',
'Comm_G_Agents_Body' => 'مندوب المبيعات هو الشخص الذي يحصل على العمولة. لا يلزم أن يكون المندوب مستخدمًا للنظام: يمكن أن يكون المُحيلون أو الموزعون الخارجيون مندوبين أيضًا، ويحصلون على العمولة كلما اختيروا في مبيعة.',
'Comm_G_F_Agent_Name' => 'الاسم الظاهر في المبيعات والتقرير والإيصالات.',
'Comm_G_F_Agent_Code' => 'مرجع اختياري مثل رقم الموظف. قابل للبحث في قائمة المندوبين.',
'Comm_G_F_Agent_User' => 'يربط المندوب بمستخدم من الموظفين. تُنسب المبيعات التي يجريها ذلك المستخدم (أو التي يُختار فيها كبائع في نقاط البيع) إلى هذا المندوب تلقائيًا.',
'Comm_G_F_Agent_Active' => 'لا يحصل المندوبون غير النشطين على أي عمولة من المبيعات الجديدة ويختفون من قوائم اختيار المندوبين. تبقى عمولاتهم السابقة.',
'Comm_G_T_Rules' => 'قواعد العمولات: شرح كل حقل',
'Comm_G_Rules_Body' => 'تحدد القاعدة المبلغ المدفوع عن المبيعة. استخدم مربع «جرّب قاعدة» أعلاه للتحقق من القاعدة قبل حفظها.',
'Comm_G_F_Rule_Program' => 'البرنامج الذي تنتمي إليه القاعدة. لا تعمل القاعدة إلا عندما يكون ذلك البرنامج نشطًا وضمن تاريخه.',
'Comm_G_F_Rule_Type' => 'النسبة المئوية تدفع حصة من المبلغ الأساسي. أما الثابت فيدفع المبلغ نفسه على كل عملية بيع مؤهلة مهما كان حجمها.',
'Comm_G_F_Rule_Source' => 'المبلغ الذي تُحتسب منه النسبة. إجمالي البيع هو الإجمالي الكلي للبيع. المبلغ المدفوع هو ما دفعه العميل عند احتساب العمولة.',
'Comm_G_F_Rule_Value' => 'النسبة المئوية (5 تعني 5%) أو المبلغ الثابت، حسب النوع.',
'Comm_G_F_Rule_Min' => 'اختياري. المبيعات التي يقل مبلغها الأساسي عن هذا الحد لا تكسب شيئًا من هذه القاعدة. أما البيع المساوي للحد تمامًا فيكسب.',
'Comm_G_F_Rule_Cap' => 'اختياري. أقصى ما يمكن أن تدفعه هذه القاعدة على عملية بيع واحدة. يعمل مع القواعد النسبية والثابتة.',
'Comm_G_F_Rule_Applies' => 'جميع المندوبين: يكسب كل مندوب من هذه القاعدة. مندوب محدد: المندوب الذي تختاره فقط. قاعدة المندوب المحدد التي لم يُختر لها مندوب لا تدفع لأحد أبدًا.',
'Comm_G_F_Rule_Priority' => 'في البرنامج المضبوط على «تدفع القاعدة ذات الأولوية الأعلى فقط»، تفوز القاعدة المؤهلة صاحبة الرقم الأعلى وتُتجاوز البقية. عند التساوي، تتقدم قاعدة المندوب المحدد على قاعدة جميع المندوبين. في البرنامج المضبوط على «تدفع كل قاعدة مطابقة»، تحدد الأولوية الترتيب فقط.',
'Comm_G_F_Rule_Active' => 'ألغِ تحديدها لإيقاف هذه القاعدة وحدها مؤقتًا. العمولات التي أنشأتها سابقًا لا تتأثر.',
'Comm_G_T_Stacking' => 'عدة قواعد على عملية بيع واحدة',
'Comm_G_Stacking_Body' => 'يحدد كل برنامج كيفية جمع قواعده (إعداد «عند تطابق عدة قواعد» في البرنامج).

تدفع القاعدة ذات الأولوية الأعلى فقط (الافتراضي للبرامج الجديدة): تُجرَّب القواعد من الأولوية الأعلى نزولًا، وأول قاعدة تتأهل للبيع هي التي تدفع. تتأهل القاعدة عندما يبلغ البيع حدها الأدنى ويكون الناتج أكبر من 0. هذا يسهّل الشرائح: «7% على المبيعات من 10,000 فأكثر» بأولوية 10 و«5%» بأولوية 0. لمنح سارة نسبة خاصة، أضف لها قاعدة مندوب محدد بأولوية أعلى من قاعدة جميع المندوبين.

تدفع كل قاعدة مطابقة: تدفع جميع القواعد المطابقة وتُجمع المبالغ. قاعدة جميع المندوبين بنسبة 3% مع قاعدة مندوب محدد بنسبة 2% لسارة تمنح سارة 5%.

البرامج مستقلة عن بعضها: كل برنامج نشط يدفع بمفرده، لذا يمكن أن يكسب البيع من برنامج أساسي وبرنامج حملة في الوقت نفسه.',
'Comm_G_T_Paying' => 'الدفع للمندوبين بإيصالات العمولات',
'Comm_G_Paying_Body' => 'افتح إيصالات العمولات وانقر إضافة. اختر المندوب: ستُعرض عمولاته المعتمدة. حدد التي تدفعها؛ يُملأ المبلغ بإجماليها ويمكنك تعديله. يُملأ المرجع تلقائيًا (CR-000001, CR-000002...)، ويمكنك إضافة طريقة الدفع والتاريخ وملاحظة.

حفظ الإيصال يجعل العمولات المحددة مدفوعة ويربطها بالإيصال. لا يمكن دفع إلا العمولات المعتمدة، لذا اعتمدها أولًا في تقرير العمولات.

تُعرض التسويات السالبة (المبالغ التي دُفعت للمندوب زيادةً) أيضًا. حددها مع العمولات التالية للمندوب لتُخصم من تلك الدفعة.

الإيصال سجل للصرف فقط: لا ينشئ مصروفًا ولا يحرّك أموالًا في حساباتك. إذا كنت تتابع المدفوعات في المصروفات أو المحاسبة، فسجّلها هناك أيضًا.',
'Comm_G_T_Snapshot' => 'عندما يتغير البيع',
'Comm_G_Snapshot_Body' => 'تتبع العمولات البيع. كلما تغيّر بيع له عمولات، يُعاد احتسابها من أرقامه الحالية: إجمالي البيع ناقص المرتجعات المستلمة، والمبلغ المدفوع ناقص المبالغ المستردة.

العمولات غير المدفوعة (معلقة أو معتمدة) تُحدَّث ببساطة. العمولة المعتمدة التي يتغير مبلغها تعود إلى معلقة ليراجعها أحد مجددًا. والتي لم تعد مستحقة (حُذف البيع، أو أُرجع بالكامل، أو تغيّر المندوب) تُزال.

العمولات المدفوعة لا تتغير أبدًا. يصبح الفرق صفًا معلقًا جديدًا موسومًا بتسوية: موجبًا عندما يُستحق مبلغ إضافي (مثلًا دُفع باقي بيع بقاعدة المبلغ المدفوع)، وسالبًا عندما دُفع للمندوب زيادةً (مثلًا بعد مرتجع). اعتمدها وأدرجها في الإيصال التالي للمندوب.

تحتفظ كل عمولة بشروط القاعدة (النوع، النسبة، الحد، السقف) كما كانت عند اكتسابها أول مرة. تغيير القاعدة أو إيقافها لاحقًا لا يعيد تسعير المبيعات الأقدم عند إعادة احتسابها.',
'Comm_G_T_Permissions' => 'من يمكنه فعل ماذا',
'Comm_G_Permission' => 'الصلاحية',
'Comm_G_Lets_You' => 'ما تتيحه',
'Comm_G_P_View' => 'عرض جميع صفحات العمولات: البرامج والمندوبين والقواعد والإيصالات والتقرير وهذا الدليل.',
'Comm_G_P_Add' => 'إنشاء البرامج والمندوبين والقواعد، وتسجيل إيصالات العمولات (الدفع للمندوبين).',
'Comm_G_P_Edit' => 'تعديل البرامج والمندوبين والقواعد، واعتماد العمولات أو إلغاؤها في تقرير العمولات.',
'Comm_G_P_Delete' => 'حذف البرامج والمندوبين والقواعد.',
'Comm_G_T_Faq' => 'أسئلة وأجوبة',
'Comm_G_Q_Empty' => 'أعددت كل شيء لكن تقرير العمولات فارغ.',
'Comm_G_A_Empty' => 'تحقق من أن: البيع حُفظ بعد إنشاء القاعدة؛ وحالة البيع مكتملة؛ وللبيع مندوب (اختير في البيع، أو المستخدم الذي أنشأه مرتبط بمندوب)؛ والبرنامج نشط وتاريخ البيع ضمن تواريخه؛ والقاعدة نشطة وتنطبق على ذلك المندوب؛ والبيع يساوي الحد الأدنى للقاعدة أو يزيد عليه. تحقق أيضًا من مرشح التاريخ في التقرير: فهو يصفّي حسب تاريخ احتساب العمولة.',
'Comm_G_Q_Twice' => 'حصل مندوب على عمولتين في عملية بيع واحدة.',
'Comm_G_A_Twice' => 'دفعت قاعدتان: إما أن البرنامج مضبوط على «تدفع كل قاعدة مطابقة»، أو أن القاعدتين في برنامجين نشطين مختلفين (كل برنامج يدفع بمفرده). اضبط البرنامج على «تدفع القاعدة ذات الأولوية الأعلى فقط» إذا كان يجب أن تدفع قاعدة واحدة. إعادة حفظ البيع لا تكرر العمولة أبدًا.',
'Comm_G_Q_Rate' => 'إذا غيّرت نسبة قاعدة، هل تتغير العمولات القديمة؟',
'Comm_G_A_Rate' => 'لا. تحتفظ كل عمولة بشروط القاعدة التي اكتُسبت بموجبها، حتى عند إعادة احتساب بيعها لاحقًا. تُستخدم النسبة الجديدة للعمولات المكتسبة من الآن فصاعدًا.',
'Comm_G_Q_Return' => 'أرجع العميل البضاعة. ماذا يحدث للعمولة؟',
'Comm_G_A_Return' => 'تُخفَّض تلقائيًا. المرتجع المستلم يخفض إجمالي البيع والاسترداد يخفض المبلغ المدفوع. إذا لم تُدفع العمولة بعد، فإنها تُحدَّث (أو تُزال في حالة الإرجاع الكامل). وإذا كانت مدفوعة، تُضاف تسوية سالبة وتُخصم من الإيصال التالي للمندوب.',
'Comm_G_Q_Wrong_Agent' => 'نسبت البيع إلى المندوب الخطأ. كيف أصلح ذلك؟',
'Comm_G_A_Wrong_Agent' => 'عدّل البيع، واختر مندوب المبيعات الصحيح واحفظ. تنتقل العمولات إلى المندوب الصحيح. إذا كان المندوب الأول قد تقاضى المبلغ، تُضاف له تسوية سالبة.',
'Comm_G_Q_Inactive' => 'ماذا يحدث عند تعطيل مندوب؟',
'Comm_G_A_Inactive' => 'يتوقف عن الكسب من المبيعات الجديدة ويُخفى من قوائم اختيار المندوبين. تبقى عمولاته الحالية، ويمكن اعتمادها ودفعها، وتظل تتبع التغييرات على مبيعاته. البيع الذي حُفظ مع اختيار ذلك المندوب لن يتحول إلى مندوب آخر.',
'Comm_G_Q_Partial' => 'كيف تتعامل قواعد المبلغ المدفوع مع الدفعات الجزئية؟',
'Comm_G_A_Partial' => 'البيع غير المدفوع لا يكسب شيئًا. تُنشأ العمولة عند استلام أول مبلغ (عند الدفع أو عند إضافة دفعة) وتزداد مع ورود دفعات أخرى. إذا كان جزء منها قد دُفع، يصل الباقي كتسوية موجبة.',
'Comm_G_Q_Undo' => 'هل يمكنني التراجع عن دفعة أو إلغاء؟',
'Comm_G_A_Undo' => 'الدفعة، لا: حالة مدفوعة نهائية ولا يمكن تعديل الإيصالات أو حذفها، لذا راجع العمولات المحددة والمبلغ قبل الحفظ. الإلغاء، نعم: حدد الصف في تقرير العمولات وانقر إعادة الاحتساب، أو احفظ البيع مجددًا في تعديل البيع.',
'Comm_G_Q_Dates' => 'أي تاريخ تستخدمه تواريخ البرنامج؟',
'Comm_G_A_Dates' => 'تاريخ البيع نفسه، لا يوم حفظه. البيع المؤرخ بالشهر الماضي يستخدم فقط البرامج التي كانت سارية الشهر الماضي.',
'Comm_G_When_Changes' => 'بعد ذلك، أي تغيير على بيع له عمولات يحدّثها تلقائيًا: تعديل الدفعات أو حذفها، والمرتجعات والمبالغ المستردة، وخروج الحالة من مكتملة، أو حذف البيع.',
'Comm_G_F_Program_Mode' => 'ما يحدث عندما تتطابق عدة قواعد في هذا البرنامج مع البيع نفسه. «تدفع القاعدة ذات الأولوية الأعلى فقط»: تُجرَّب القواعد من الأولوية الأعلى نزولًا وأول قاعدة تتأهل هي التي تدفع. «تدفع كل قاعدة مطابقة»: تدفع جميعها وتُجمع المبالغ.',
'Comm_G_Q_Mode_Old' => 'حددت الأولويات، لكن القواعد ما زالت تُجمع.',
'Comm_G_A_Mode_Old' => 'هذا البرنامج مضبوط على «تدفع كل قاعدة مطابقة». البرامج التي أُنشئت قبل وجود هذا الإعداد تحتفظ بهذا السلوك حتى لا تتغير مدفوعاتها. عدّل البرنامج واختر «تدفع القاعدة ذات الأولوية الأعلى فقط».',
'Comm_G_Q_Negative' => 'لماذا توجد عمولة سالبة؟',
'Comm_G_A_Negative' => 'إنها تسوية: دُفع للمندوب أكثر مما يكسبه البيع الآن، بسبب مرتجع أو استرداد أو إجمالي أقل أو تغيير المندوب أو حذف البيع. اعتمدها وحددها في الإيصال التالي للمندوب لتُخصم.',
'Comm_Rule_Mode' => 'عند تطابق عدة قواعد',
'Comm_Mode_Highest' => 'تدفع القاعدة ذات الأولوية الأعلى فقط',
'Comm_Mode_All' => 'تدفع كل قاعدة مطابقة (تُجمع المبالغ)',
'Comm_Mode_Highest_Short' => 'الأولوية الأعلى تفوز',
'Comm_Mode_All_Short' => 'القواعد تُجمع',
'Comm_Mode_Highest_Help' => 'تُجرَّب القواعد من الأولوية الأعلى نزولًا؛ أول قاعدة تتأهل للبيع تدفع وتُتجاوز البقية. مناسب للشرائح، مثلًا 7% فوق 10,000 بأولوية 10 و5% لكل ما عدا ذلك بأولوية 0.',
'Comm_Mode_All_Help' => 'كل قاعدة تطابق المندوب تدفع على البيع، فتُجمع المبالغ. تحدد الأولوية الترتيب فقط.',
'Comm_Priority_Help_Highest' => 'هذا البرنامج يدفع فقط القاعدة المؤهلة ذات الأولوية الأعلى. امنح هذه القاعدة أولوية أعلى من القواعد التي يجب أن تتغلب عليها. عند التساوي، تتقدم قاعدة المندوب المحدد على قاعدة جميع المندوبين.',
'Comm_Priority_Help_All' => 'هذا البرنامج يدفع كل قاعدة مطابقة، لذا تُضاف هذه القاعدة إلى غيرها. تحدد الأولوية الترتيب فقط.',
'Comm_Recalculate' => 'إعادة الاحتساب',
'Comm_Recalculate_Help' => 'يعيد احتساب مبيعات الصفوف المحددة من أرقامها الحالية، بما في ذلك العمولات الملغاة.',
'Comm_Adjustment' => 'تسوية',
'Comm_Adjustment_Help' => 'تصحيح لعمولة دُفعت مسبقًا لأن البيع تغيّر بعد ذلك. المبلغ السالب يُخصم من الإيصال التالي للمندوب.',
'Comm_Cancel_Confirm' => 'إلغاء العمولات المحددة؟',
'Comm_Cancel_Confirm_Help' => 'لن تُدفع، وتبقى ملغاة عند ورود دفعات أو مرتجعات لاحقًا. حفظ البيع في تعديل البيع أو النقر على إعادة الاحتساب يعيد احتسابها.',
