'Rst_Guide_Step_Floor_Help' => 'أضف مناطقك (داخلية، تراس…) وطاولاتها مع عدد المقاعد. يُنشئ خيار «إضافة عدة طاولات» الطاولات T1–T20 دفعة واحدة.',
'Rst_Guide_Step_Stations' => 'محطات المطبخ',
'Rst_Guide_Step_Stations_Ok' => '{n} محطات.',
'Rst_Guide_Step_Stations_Help' => 'تقسّم المحطات (الشواء، القلي، الباردة، الحلويات، المشروبات…) شاشة المطبخ بحيث يرى كل طاهٍ أطباقه فقط.',
'Rst_Guide_Step_Dishes' => 'الأطباق والإضافات',
'Rst_Guide_Step_Dishes_Ok' => 'تم إعداد {n} أطباق، و{groups} مجموعات إضافات.',
'Rst_Guide_Step_Dishes_Help' => 'الأطباق هي منتجاتك العادية. من المطعم › القائمة حدّد لها محطة ووقت تحضير ووسومًا غذائية ومجموعات إضافات (الأحجام، الإضافات).',
'Rst_Guide_Step_Payments' => 'المدفوعات',
'Rst_Guide_Step_Payments_Ok' => '{n} طرق دفع جاهزة، بما فيها النقد، وزبون افتراضي لفواتير الزوار دون حجز.',
'Rst_Guide_Step_Payments_Help' => 'تحتاج الفواتير إلى طريقة دفع نشطة واحدة على الأقل، وطريقة نقدية (يُعطى الباقي من النقد)، وزبون افتراضي في إعدادات النظام.',
'Rst_Guide_Step_Staff' => 'صلاحيات الموظفين',
'Rst_Guide_Step_Staff_Help' => 'الأدوار التي يمكنها أخذ الطلبات: {waiters}، واستخدام شاشة المطبخ: {kitchen}، واستلام المدفوعات: {cashiers}. امنح كل دور ما تحتاجه وظيفته فقط (انظر «من يفعل ماذا»).',
'Rst_Guide_Step_First' => 'فاتورتك الأولى',
'Rst_Guide_Step_First_Ok' => 'تم إصدار {n} فواتير حتى الآن.',
'Rst_Guide_Step_First_Help' => 'أجلس طاولة تجريبية على مخطط الصالة، وأضف طبقًا، وأرسله، وعيّنه كجاهز على شاشة المطبخ ثم استلم الدفع.',
'Rst_Guide_Step_Qr' => 'الطلب من الطاولة عبر QR',
'Rst_Guide_Step_Qr_On' => 'مفعّل. لدى {n} طاولات رمز QR.',
'Rst_Guide_Step_Qr_Help' => 'يمسح الضيوف رمزًا على الطاولة، ويختارون الأطباق من هواتفهم ويرسلونها إلى طلب الطاولة. فعّل ذلك من إعدادات المطعم، ثم اطبع الرموز.',
'Rst_Guide_Step_Booking' => 'حجز الطاولات عبر الإنترنت',
'Rst_Guide_Step_Booking_On' => 'مفعّل. تصل الحجوزات من المتجر الإلكتروني إلى قسم الحجوزات لتأكيدها.',
'Rst_Guide_Step_Booking_Help' => 'دع الضيوف يحجزون طاولة من المتجر الإلكتروني. اضبط ساعات الحجز والفاصل الزمني وأكبر مجموعة من إعدادات المطعم.',
'Rst_Guide_Step_Store' => 'المتجر الإلكتروني وسمة المطعم',
'Rst_Guide_Step_Store_On' => 'سمة المطعم مفعّلة. تصل الطلبات الإلكترونية إلى المطبخ: {mode}.',
'Rst_Guide_Step_Store_Help' => 'من المتجر الإلكتروني › الإعدادات اختر سمة «مطعم»: تصبح الصفحة الرئيسية قائمتك، مع الإضافات والاستلام / التوصيل وحجز الطاولات.',
'Rst_Guide_How' => 'كيف يعمل',
'Rst_Guide_Service' => 'الخدمة خطوة بخطوة',
'Rst_Guide_Service_1_T' => 'الإجلاس',
'Rst_Guide_Service_1' => 'على مخطط الصالة اختر طاولة متاحة، وأدخل عدد الضيوف والنادل، ثم «إجلاس الضيوف وأخذ الطلب». تُجلس المجموعة المحجوزة من حجزها.',
'Rst_Guide_Service_2_T' => 'الطلب',
'Rst_Guide_Service_2' => 'انقر على الأطباق في شاشة الطلب. اختر الإضافات والمقعد والمرحلة؛ وأضف ملاحظة للمطبخ. أوقف مرحلة مؤقتًا لإطلاقها لاحقًا.',
'Rst_Guide_Service_3_T' => 'الإرسال',
'Rst_Guide_Service_3' => 'يضع «إرسال» الأطباق الجديدة في تذكرة مطبخ واحدة. يمكن تعديل الأطباق غير المرسلة أو إزالتها؛ وبعد ذلك لا يمكن إلا إلغاؤها مع ذكر السبب.',
'Rst_Guide_Service_4_T' => 'الطهي',
'Rst_Guide_Service_4' => 'تعرض شاشة المطبخ التذكرة في كل محطة. يبدأ الطهاة العمل عليها، ويحدّدون الأطباق عند الانتهاء منها، وينجزونها عندما يجهز كل شيء.',
'Rst_Guide_Service_5_T' => 'التقديم',
'Rst_Guide_Service_5' => 'تظهر الأطباق الجاهزة على مخطط الصالة وشاشة الطلب. يأخذها النادل وينقر «تعيين كمُقدَّم».',
'Rst_Guide_Service_6_T' => 'الفاتورة',
'Rst_Guide_Service_6' => 'يطبع «الفاتورة والدفع» الفاتورة ويستلم الدفع: الفاتورة كاملة، أو مقسّمة بالتساوي أو حسب الصنف. كل دفعة هي عملية بيع POS عادية.',
'Rst_Guide_Service_7_T' => 'التنظيف',
'Rst_Guide_Service_7' => 'عند دفع كل شيء يُغلق الطلب وتتحول الطاولة إلى «تحتاج إلى تنظيف» (أو إلى متاحة مباشرة، حسب إعدادات المطعم).',
'Rst_Guide_Roles' => 'من يفعل ماذا',
'Rst_Guide_Roles_Help' => 'تُمنح صلاحيات المطعم لكل دور من صلاحيات المجموعات. ويمكن للمستخدم أن يحمل صلاحيات عدة أدوار.',
'Rst_Guide_Job' => 'الوظيفة',
'Rst_Guide_Give' => 'امنح هذه الصلاحيات',
'Rst_Guide_Job_Waiter' => 'النادل',
'Rst_Guide_Job_Cook' => 'الطاهي',
'Rst_Guide_Job_Cashier' => 'أمين الصندوق',
'Rst_Guide_Job_Host' => 'المضيف / الاستقبال',
'Rst_Guide_Job_Supervisor' => 'المشرف',
'Rst_Guide_Job_Manager' => 'المدير',
'Rst_Guide_Menu' => 'القائمة والمحطات والإضافات',
'Rst_Guide_Menu_1' => 'يمكن أن يكون كل منتج تبيعه طبقًا. يضيف المطعم › القائمة (أو بطاقة «تفاصيل الطبق» في نموذج المنتج) معلومات المطعم.',
'Rst_Guide_Menu_2' => 'تحتوي مجموعات الإضافات على خيارات بسعر: «الحجم» (اختر 1) أو «الإضافات» (حتى 3). تُفحص القواعد في كل طلب، بما في ذلك الطلبات الإلكترونية.',
'Rst_Guide_Menu_3' => 'يمكن للإضافة أن تستهلك مكوّنًا: اربط «جبن إضافي» بمنتج الجبن لديك وستخصم كل إضافة من ذلك المخزون.',
'Rst_Guide_Menu_4' => 'عيّن الطبق كنافد لهذا اليوم بمفتاح واحد؛ ويعود تلقائيًا في اليوم التالي. تحدد أوقات الوجبات (الإفطار، الغداء، العشاء) متى يُعرض الطبق.',
'Rst_Guide_Menu_5' => 'الوصفة هي منتج مجموعة: عند تفعيل المخزون الافتراضي للمجموعات، يخصم بيع الطبق مكوّناته من المخزون.',
'Rst_Guide_Kitchen' => 'شاشة المطبخ',
'Rst_Guide_Kitchen_1' => 'افتح المطعم › المطبخ على شاشة في المطبخ. اختر المحطة؛ وتظهر الأطباق التي ليس لها محطة في جميع المحطات.',
'Rst_Guide_Kitchen_2' => 'تتحول التذاكر إلى اللون الكهرماني ثم الأحمر أثناء الانتظار (إعدادات المطعم › متأخر بعد N دقيقة). وتُعلن نغمة عن التذاكر الجديدة.',
'Rst_Guide_Kitchen_3' => 'بدء ← تحديد الأطباق ← إنجاز. يُنهي «تم في هذه المحطة» أطباق هذه المحطة فقط في التذكرة المشتركة.',
'Rst_Guide_Kitchen_4' => 'تبقى التذاكر المُقدَّمة 15 دقيقة لإمكانية استعادتها عند الخطأ. ويمكن طباعة التذاكر على طابعة 80 mm.',
'Rst_Guide_Kitchen_5' => 'تُميَّز الطلبات الواردة من المتجر الإلكتروني ومن رموز QR للطاولات بعلامة «عبر الإنترنت» أو «QR» على تذكرتها.',
'Rst_Guide_Bills' => 'الفواتير والمدفوعات',
'Rst_Guide_Bills_1' => 'كل دفعة هي عملية بيع POS عادية: يعمل المخزون والصندوق والمحاسبة ونقاط الولاء والفوترة الإلكترونية كما في نقطة البيع.',
'Rst_Guide_Bills_2' => 'رسوم الخدمة نسبة مئوية من الأطباق قبل الضريبة، لتناول الطعام في المطعم (أو لكل طلب، حسب إعدادك). والبقشيش نسبة مئوية محددة مسبقًا أو مبلغ.',
'Rst_Guide_Bills_3' => 'يتطلب الخصم صلاحية «خصومات المطعم» ويُحدّ بأكبر خصم في إعدادات المطعم.',
'Rst_Guide_Bills_4' => 'يكون التقريب نزولًا إلى الفاصل المحدد، لصالح الضيف، على الدفعة التي تسدّد الفاتورة.',
'Rst_Guide_Bills_5' => 'التقسيم بالتساوي: عملية بيع واحدة، وسطر دفع واحد لكل شخص (الحصص حتى السنت). التقسيم حسب الصنف: تصبح أطباق كل ضيف عملية بيع مستقلة؛ اختر مقعدًا لتحديد أطباقه.',
'Rst_Guide_Bills_6' => 'إذا تغيّرت الفاتورة بعد عرضها (أُضيف طبق من رمز QR، أو تغيّر البقشيش)، يُرفض الدفع حتى لا يُحاسَب الضيف أبدًا على شيء لم يره.',
'Rst_Guide_Bills_7' => 'لا يمكن إلغاء الأطباق المدفوعة. وإذا أُلغي الجزء غير المدفوع من الطلب، يُغلق الطلب كمدفوع ويمكن تنظيف الطاولة.',
'Rst_Guide_Bookings' => 'الحجوزات وقائمة الانتظار',
'Rst_Guide_Bookings_1' => 'تحجز الحجوزات الطاولة طوال مدتها (الافتراضية في إعدادات المطعم). ولا يمكن أن يتداخل حجزان على طاولة واحدة.',
'Rst_Guide_Bookings_2' => 'يعرض مخطط الصالة الحجز التالي لكل طاولة وينبّه عند اقتراب موعده؛ ويُجلس «لقد وصلوا — إجلاس» المجموعة.',
'Rst_Guide_Bookings_3' => 'بعد وقت عدم الحضور يمكن تعيين المجموعة المتأخرة كعدم حضور؛ ويمكن استعادة الحجز عند الخطأ.',
'Rst_Guide_Bookings_4' => 'تحفظ قائمة الانتظار ترتيب الزوار دون حجز مع وقت الانتظار المُبلَّغ لهم. اتصل بهم أو راسلهم عبر WhatsApp عندما تجهز طاولة، ثم أجلسهم.',
'Rst_Guide_Bookings_5' => 'تصل الحجوزات عبر الإنترنت بحالة «محجوز» (وتعدّها شارة في الشريط الجانبي) لتأكيدها.',
'Rst_Guide_Online' => 'الطلبات الإلكترونية وقوائم QR والحجز عبر الإنترنت',
'Rst_Guide_Online_1' => 'مع سمة متجر المطعم تصبح الصفحة الرئيسية للمتجر الإلكتروني قائمتك، مع الإضافات والمرشحات الغذائية؛ ويدفع المتسوقون عند إتمام الطلب كالمعتاد.',
'Rst_Guide_Online_2' => 'يحدد خيار «الطلبات الإلكترونية إلى المطبخ» متى تصل إلى شاشة المطبخ: عند تقديمها (مدفوعة، أو من زبون مسجّل الدخول يدفع عند التوصيل / الاستلام)، أو عند قبولها، أو أبدًا.',
'Rst_Guide_Online_3' => 'تفتح رموز QR للطاولات (إعداد الصالة › رموز QR للطاولات) القائمة لتلك الطاولة. ويُبطل «رابط جديد» الرمز المطبوع.',
'Rst_Guide_Online_4' => 'تنتظر طلبات QR في طلب الطاولة حتى يرسلها النادل، ما لم يكن خيار «إرسال طلبات QR مباشرة إلى المطبخ» مفعّلًا. ويدفع الضيوف لدى الموظفين.',
'Rst_Guide_Online_5' => 'لا يعرض الحجز عبر الإنترنت إلا الأوقات التي تتوفر فيها طاولة تناسب المجموعة طوال مدة الحجز، ويحدّ كل رقم هاتف بـ 3 حجوزات قادمة.',
'Rst_Guide_Online_6' => 'كل ذلك جزء من المتجر الإلكتروني: يجب أن يكون مفعّلًا ومُضمّنًا في خطتك.',
'Rst_Guide_Reports' => 'لوحة التحكم والتقارير',
'Rst_Guide_Reports_1' => 'تعرض لوحة التحكم اليوم مقارنةً بنفس اليوم من الأسبوع الماضي: المبيعات والفواتير والضيوف ومتوسط الفاتورة والإلغاءات والخصومات، إضافةً إلى ما يحدث الآن.',
'Rst_Guide_Reports_2' => 'المبيعات هي فواتير المطعم إضافةً إلى الطلبات الإلكترونية التي وصلت إلى المطبخ. مبيعات الأطباق والهوامش قبل الضريبة، باستخدام تكلفة كل منتج.',
'Rst_Guide_Reports_3' => 'التقارير: المبيعات حسب اليوم وطريقة الدفع، والأطباق، والإلغاءات (مع الأسباب)، والموظفون، وأوقات المطبخ، والحجوزات — ويُصدَّر كل منها إلى Excel.',
'Rst_Guide_Reports_4' => 'الموظفون المقيّدون ببعض الفروع لا يرون إلا فروعهم؛ أما الطلبات بلا فرع فمشتركة بين الجميع.',
'Rst_Guide_Faq' => 'معلومات مفيدة',
'Rst_Guide_Faq_1_Q' => 'دُفع طلب سفري قبل أن أضغط «إرسال». هل سيُطهى؟',
'Rst_Guide_Faq_1_A' => 'نعم. يرسل الدفع إلى المطبخ أي أطباق لم تُرسل بعد.',
'Rst_Guide_Faq_2_Q' => 'لماذا لا أستطيع تنظيف طاولة؟',
'Rst_Guide_Faq_2_A' => 'لا يزال طلبها يحتوي على أطباق غير مدفوعة. استلم الدفع، أو ألغِ ما لم يُؤكل، أو ألغِ الطلب (فقط عندما لا يكون أي شيء مدفوعًا بعد).',
'Rst_Guide_Faq_3_Q' => 'تم ضم طاولتين معًا. ماذا يحدث لطلباتهما؟',
'Rst_Guide_Faq_3_A' => 'ينقل «دمج الطاولات» أطباق الطاولة الثانية (وأي مدفوعات) إلى طلب الطاولة الرئيسية؛ ويفصل «إلغاء الدمج» الطاولات مجددًا.',
'Rst_Guide_Faq_4_Q' => 'هل يمكن استخدام Stripe لمدفوعات البطاقات هنا؟',
'Rst_Guide_Faq_4_A' => 'لا. تتطلب مدفوعات البطاقات عبر Stripe نموذج البطاقة في POS؛ أما لجهاز البطاقات فأضف طريقة دفع مثل «بطاقة» واستخدمها في الفاتورة.',
'Rst_Guide_Faq_5_Q' => 'طبق نفدت كميته في فرع واحد فقط.',
'Rst_Guide_Faq_5_A' => 'يُخصم المخزون من فرع الطلب (منطقة الطاولة، وإلا فالفرع الافتراضي في إعدادات المطعم). استخدم «نفد اليوم» لإيقاف الطلبات بسرعة.',
'Rst_Guide_Faq_6_Q' => 'هل أحتاج إلى طابعة؟',
'Rst_Guide_Faq_6_A' => 'لا. تُطبع الفواتير والإيصالات وتذاكر المطبخ من المتصفح على أي طابعة؛ وتناسبها طابعات الإيصالات 80 mm أكثر.',
'Rst_Guide_Faq_7_Q' => 'من أين تأتي قوائم المطعم في المتجر الإلكتروني؟',
'Rst_Guide_Faq_7_A' => 'من نفس المنتجات والفئات والإضافات. تبقى المنتجات المخفية من المتجر الإلكتروني، والفئات غير المعروضة في المتجر، خارج القائمة الإلكترونية وقائمة QR.',

// Rental — business types + website booking (Rental store theme).
'Rental_Website_Not_Ready' => 'ثبّت آخر تحديث لاستخدام أنواع النشاط والحجز عبر الموقع.',
'Rental_Business_Type' => 'نوع النشاط',
'Rental_Business_Type_Help' => 'حدّد ما تؤجّره. سيعرض نموذج العنصر والفئات والمرشحات وموقعك هذه الأنواع وحقولها فقط.',
'Rental_Business_Type_All' => 'لم يُحدَّد شيء: جميع الأنواع متاحة.',
'Rental_Website_Booking' => 'الحجز عبر الموقع',
'Rental_Website_Theme_Off' => 'يستخدم متجرك الإلكتروني سمة أخرى. اختر سمة التأجير في إعدادات المتجر لنشر عناصر التأجير.',
'Rental_Open_Store_Settings' => 'فتح إعدادات المتجر',
'Rental_Website_Booking_Help' => 'يختار الزوار التواريخ على موقعك ويرسلون طلب حجز. يصل إلى الحجوزات كحجز مؤقت: أكّده، أو حوّله إلى عقد، أو ألغِه.',
'Rental_Website_Hold' => 'الاحتفاظ بالطلب لمدة',
'Rental_Website_Hold_Help' => 'تبقى العناصر محجوزة طوال هذه المدة ريثما ترد. ويحتفظ التأكيد بها حتى نهاية التأجير.',
'Rental_Website_Notice' => 'الحد الأدنى للإشعار المسبق',
'Rental_Website_Notice_Help' => 'أقرب موعد يمكن أن يبدأ فيه الحجز عبر الموقع.',
'Rental_Website_Ahead' => 'الحجز حتى',
'Rental_Website_Ahead_Help' => 'إلى أي مدى مسبقًا يمكن للزوار الحجز.',
'Rental_Website_Login' => 'تسجيل الدخول مطلوب',
'Rental_Website_Login_Help' => 'لا يمكن إرسال الطلبات إلا للزبائن الذين لديهم حساب في المتجر.',
'Rental_Pickup_Locations' => 'مواقع الاستلام',
'Rental_Pickup_Locations_Help' => 'المركبات: الأماكن التي يمكن للزبائن اختيارها للاستلام والإرجاع. اتركه فارغًا إذا كان كل شيء يُستلم من فرعك.',
'Rental_Pickup_Locations_Placeholder' => 'مثال: المطار؛ مكتب وسط المدينة',
