'Mkg_Guide_Faq' => 'أسئلة شائعة',
'Mkg_Guide_Faq_1_Q' => 'حملتي تبقى في حالة الإرسال ولا يُرسل شيء.',
'Mkg_Guide_Faq_1_A' => 'لم يلتقطها المُرسل الخلفي. بعد 30 دقيقة دون تقدّم يظهر زر "إرسال الآن" مجددًا: انقره للاستئناف. إذا تكرر ذلك، اطلب من مسؤول المنصة التحقق من أن المهام الخلفية (عامل قائمة الانتظار) تعمل.',
'Mkg_Guide_Faq_2_Q' => 'يظهر للمستلمين "تم التخطي: قناة البريد الإلكتروني معطّلة".',
'Mkg_Guide_Faq_2_A' => 'فعّل "تمكين البريد الإلكتروني" في إعدادات التسويق، ثم أرسل الحملة مجددًا.',
'Mkg_Guide_Faq_3_Q' => 'يظهر للمستلمين "لم يتم إعداد خادم بريد".',
'Mkg_Guide_Faq_3_A' => 'تُرسل حملات البريد الإلكتروني فقط عبر خادم البريد الخاص بك. أضفه في الإعدادات > إعدادات البريد.',
'Mkg_Guide_Faq_4_Q' => 'عدد من استلموا الرسالة أقل من عدد أفراد شريحتي.',
'Mkg_Guide_Faq_4_A' => 'يتم تخطي الزبائن الذين ليس لديهم بريد إلكتروني (للبريد الإلكتروني) أو رقم هاتف (لـ SMS وWhatsApp). افتح الحملة لمعرفة من تم تخطيه ولماذا.',
'Mkg_Guide_Faq_5_Q' => 'هل تعني "مُرسلة" أن الزبون استلمها؟',
'Mkg_Guide_Faq_5_A' => '"مُرسلة" تعني أن خادم البريد أو البوابة لديك قبل الرسالة. لا يتم تتبّع الوصول إلى صندوق الوارد أو الفتح أو تصفية البريد العشوائي.',
'Mkg_Guide_Faq_6_Q' => 'هل يمكنني تعديل حملة بعد إرسالها؟',
'Mkg_Guide_Faq_6_A' => 'لا. الحملات قيد الإرسال والمُرسلة مقفلة؛ أنشئ حملة جديدة بدلًا من ذلك.',
'Mkg_Guide_Faq_7_Q' => 'رسائل WhatsApp الخاصة بي لا تصل.',
'Mkg_Guide_Faq_7_A' => 'بعد مرور أكثر من 24 ساعة على آخر رسالة من الزبون إليك، لا يسلّم WhatsApp إلا القوالب المعتمدة من Meta. استخدم WhatsApp Cloud API واختر قالبًا معتمدًا في الحملة.',
'Mkg_Guide_Faq_8_Q' => 'إذا أرسلت حملة مجددًا، هل سيستلمها الزبائن مرتين؟',
'Mkg_Guide_Faq_8_A' => 'استئناف حملة عالقة يرسل فقط إلى المستلمين الذين لا يزالون معلّقين، فلا تُرسل رسائل مجددًا لمن تم الوصول إليهم. أما إعادة إرسال حملة فاشلة فتبدأ من جديد بقائمة جديدة.',

