'Pd_Installments' => 'الأقساط',
'Pd_Single_Payment' => 'دفعة واحدة',
'Pd_Guide_How_Title' => 'كيف يعمل',
'Pd_Guide_How_Intro' => 'جهاز نقطة البيع هو جهاز دفع بالبطاقات أو آلة تسجيل نقدية ضريبية بجوار الصندوق. يرسل إليه Stocky المبلغ، وينتظر دفع العميل، ولا يسجّل الدفعة إلا بعد موافقة الجهاز عليها.',
'Pd_Guide_Step_1' => 'أضف الجهاز هنا: الطراز والمستودع وطريقة الدفع التي تُسجَّل بها مدفوعات البطاقة (مثل "بطاقة ائتمان").',
'Pd_Guide_Step_2' => 'اختر طريقة وصول Stocky إليه: برنامج وسيط محلي على كمبيوتر أمين الصندوق، أو API السحابي لمزوّد الخدمة. أدخل المعرّفات والمفاتيح الواردة من البنك أو المزوّد.',
'Pd_Guide_Step_3' => 'اضغط اختبار الاتصال. يجب اختبار الأجهزة المرتبطة ببرنامج وسيط من كمبيوتر أمين الصندوق الذي يعمل عليه البرنامج.',
'Pd_Guide_Step_4' => 'في نقطة البيع، اختر طريقة الدفع تلك، واضغط "خصم على الجهاز" ودع العميل يدفع. يمكن إتمام البيع بمجرد موافقة الجهاز.',
'Pd_Guide_Step_5' => 'راجع المعاملات بحثًا عن دفعات بطاقة تمت بدون بيع (مثل عملية دفع تم التخلي عنها) وقم بإلغائها أو استردادها.',
'Pd_Guide_Bridge_Text' => 'للأجهزة التي تعمل عبر SDK من المورّد على كمبيوتر أمين الصندوق (اقتران USB أو تسلسلي أو LAN). لا يستطيع المتصفح استخدام SDK مباشرة، لذا يغلّفه برنامج وسيط صغير ويستمع على هذا الكمبيوتر.',
'Pd_Guide_Bridge_Point_1' => 'ترسل نقطة البيع كل طلب إلى رابط الوسيط من متصفح أمين الصندوق؛ ولا يحتاج خادم Stocky أبدًا إلى الوصول إلى شبكة متجرك.',
'Pd_Guide_Bridge_Point_2' => 'تُوقَّع الطلبات والاستجابات بالسر المشترك، فلا يمكن تزوير موافقة من المتصفح.',
'Pd_Guide_Bridge_Point_3' => 'ثبّت برنامج الوسيط وشغّله على كل كمبيوتر يستقبل مدفوعات البطاقة على هذا الجهاز.',
'Pd_Guide_Cloud_Text' => 'للمزوّدين الذين يصلون إلى الجهاز عبر الإنترنت. يستدعي خادم Stocky واجهة API، فلا حاجة لتثبيت أي شيء على كمبيوتر أمين الصندوق.',
'Pd_Guide_Cloud_Point_1' => 'يجب أن يكون رابط API بصيغة https:// وعلى عنوان عام.',
'Pd_Guide_Cloud_Point_2' => 'أثناء دفع العميل، يستعلم Stocky عن الحالة كل ثانيتين، لذا يجب أن تتعرّف نقطة نهاية الحالة على الدفعة من خلال مرجعها؛ وإذا استجاب API قبل انتهاء البطاقة ("pending")، يحسم الاستعلام الدوري النتيجة.',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'جهاز IDE280 هو آلة تسجيل نقدية ضريبية من الجيل الجديد (YN ÖKC) مزوّدة بقارئ بطاقات. يُدمج عادةً عبر ECR / GMP3 SDK من Ingenico، أو عبر خدمة التكامل لدى البنك.',
'Pd_Guide_Ide280_Point_1' => 'اقرن الجهاز بكمبيوتر أمين الصندوق كما هو موضّح في وثائق Ingenico / البنك، ثم وجّه برنامج الوسيط (أو إعدادات API) إليه.',
'Pd_Guide_Ide280_Point_2' => 'تُرسل المبالغ بالصيغة العشرية وبالقروش التركية kuruş (amount_minor) معًا، بالعملة TRY / 949.',
'Pd_Guide_Ide280_Point_3' => 'مع "إيصال ضريبي كامل"، يحمل كل صنف قسم الجهاز الخاص بنسبة ضريبته — طابق أقسام ضريبة القيمة المضافة مع طريقة برمجة الجهاز.',
'Pd_Guide_Protocol_Title' => 'عقد الوسيط / API',
'Pd_Guide_Protocol_Intro' => 'يتواصل Stocky مع برنامج الوسيط أو API بصيغة JSON. المسارات أدناه هي الافتراضية ويمكن تغييرها لكل جهاز ضمن متقدم.',
