'Pd_Guide_Safety_Title' => 'معلومات مفيدة',
'Pd_Guide_Safety_1' => 'لا يُحفظ البيع إلا مع دفعة جهاز مقبولة بالمبلغ نفسه؛ ولا يمكن لدفعة جهاز واحدة أن تسدّد بيعين أبدًا.',
