'Ord_Guide_PayAuto_Intro' => 'يعرض هذا العمود مقدار المدفوع من الطلب. يبدأ من اختيار العميل عند الدفع، ثم يتحدّث تلقائيًا مع تسجيل المدفوعات على البيع الذي يُنشئه تأكيد الطلب. لا يمكن تعديله من هذه الصفحة.',
'Ord_Guide_PayAuto_Paid' => 'تم استلام المبلغ كاملًا. إذا دفع العميل عبر الإنترنت من خلال بوابة دفع، فإن تأكيد الطلب يُنشئ البيع بحالة مدفوعة ويسجّل الدفعة نيابةً عنك. وإلا تتغير الحالة إلى مدفوعة بمجرد أن تغطي المدفوعات على البيع الإجمالي.',
'Ord_Guide_PayAuto_Partial' => 'تم تسجيل دفعة على البيع، لكن جزءًا من الإجمالي لا يزال مستحقًا.',
'Ord_Guide_PayAuto_Pending' => 'لم يتم استلام أي دفعة بعد: الدفع عند الاستلام أو التحويل البنكي أو طريقة دفع آجلة أخرى. تأكيد الطلب يُنشئ البيع بحالة غير مدفوعة، لذا تسجّل المبلغ بنفسك بمجرد تحصيله. راجع الخطوات أدناه.',
'Ord_Guide_PayAuto_Note' => 'حالة الدفع المعروضة هنا تتبع البيع: تتغير إلى مدفوعة جزئيًا أو مدفوعة تلقائيًا عند حفظ دفعة، وتعود عند حذف إحداها. البيع هو السجل المحاسبي، وهو ما يغذّي تقارير المدفوعات والأرباح. استخدم عرض المدفوعات على البيع لمراجعة ما أدخلته أو تعديله.',
