'Oc_G_First_Both_Text' => 'اسحب أولًا، حتى تُربط منتجات المتجر الحالية بدلًا من تكرارها، ثم ادفع لإنشاء ما ينقص المتجر. أبقِ أكواد المنتجات والموديلات متطابقة على الطرفين.',
'Oc_G_Stock_Master' => '{company} هو مصدر رقم المخزون',
'Oc_G_Stock_Master_Desc' => 'بعد المزامنة الأولى، تُكتب الكمية في المتجر دائمًا من {company}. لا يدوم أثر تعديل الكمية في OpenCart: إذ تستبدلها الحركة التالية أو الفحص الذي يجري كل ساعة.',
'Oc_G_How_Title' => 'كيف يعمل',
'Oc_G_T_Products' => 'المنتجات',
'Oc_G_Products_1' => 'يُطابَق المنتج بكوده هنا مع الموديل و SKU في المتجر. ويُحفظ الربط، فلا تؤدي إعادة تسمية المنتج لاحقًا إلى كسره.',
'Oc_G_Products_2' => 'عندما يدفع {company} منتجًا فإنه يضبط الموديل و SKU والاسم والسعر والحالة والمخزون. أما الوصف والصورة والتصنيف فلا تُكتب إلا إذا كان المنتج جديدًا في المتجر أو لا يملكها، فيبقى النص المكتوب في OpenCart كما هو.',
'Oc_G_Products_3' => 'المنتج المخفي من المتجر الإلكتروني أو غير المعروض للبيع هنا لا يُنشأ في المتجر؛ أما المنتج المربوط مسبقًا فيُعطَّل هناك بدلًا من ذلك.',
'Oc_G_T_Variants' => 'المتغيرات والخيارات',
'Oc_G_Variants_4' => 'يدعم OpenCart 4 متغيرات حقيقية (منتج بخيارات اللون والمقاس)، لكل منها مخزونه الخاص. وتُطابَق مع متغيراتك في الاتجاهين، ويُطابَق كل منها بموديله الخاص.',
'Oc_G_Variants_3' => 'لا يحتوي OpenCart 3 على متغيرات، بل خيارات فقط، مع مخزون لكل قيمة خيار. المنتج ذو الخيار الواحد (المقاس مثلًا) يُزامن بمخزون لكل قيمة، وتُطابَق القيم مع متغيراتك. أما المنتج ذو الخيارات المتعددة فتُنشأ خياراته دون مخزون لكل تركيبة: يبقى مخزونه على المنتج ككل، وتُسجَّل بنود مبيعاته على المنتج.',
'Oc_G_Variants_Multi' => 'منتج المتجر الذي يحتوي على خيارات فقط دون إنشاء متغيرات يُستورد كمنتج واحد؛ ويُشار إلى ذلك في السجلات.',
'Oc_G_T_Stock' => 'المخزون',
'Oc_G_Stock_1' => 'عند تفعيل مفتاح المخزون، تُحدِّث كل حركة هنا (بيع، مرتجع، شراء، تعديل، تحويل) المتجر خلال ثوانٍ، بعد أن تستجيب الصفحة، فلا ينتظر أمين الصندوق المتجر أبدًا.',
'Oc_G_Stock_2' => 'مرة كل ساعة يُفحص كل منتج مربوط ويُصحَّح، وهذا يغطي التغييرات الجماعية التي لا يراها الدفع المباشر. ويدفع تبويب المخزون كل شيء عند الطلب.',
'Oc_G_Stock_3' => 'الخدمات، والمنتجات المعلَّمة كمتوفرة دائمًا، والمجموعات التي مكوناتها غير محدودة تظهر كمتوفرة دائمًا في المتجر. اختر مستودعًا في تبويب الاتصال لاحتساب مخزون ذلك المستودع فقط؛ وإلا تُجمع كل المستودعات.',
'Oc_G_T_Orders' => 'الطلبات والحالات',
'Oc_G_Orders_1' => 'يُعلن المتجر فورًا عن أي طلب جديد أو معدَّل، ثم يُقرأ مجددًا عبر الاتصال الموقَّع، فلا يُوثق بأي شيء في الإشعار نفسه. وكل بضع دقائق يسحب فحصٌ ما فات أي إشعار. يصبح كل طلب عملية بيع واحدة بالمرجع OC-<order number>؛ ويُطابَق العميل بالبريد الإلكتروني أو يُنشأ.',
'Oc_G_Col_List' => 'قائمة الحالات',
'Oc_G_Col_Meaning' => 'ما تفعله هنا',
'Oc_G_Col_Default' => 'مضبوطة من متجرك',
'Oc_G_Default_Commit' => 'الحالات التي تخصم المخزون في OpenCart (Pending و Processing و Shipped و Complete افتراضيًا)',
'Oc_G_Default_Paid' => 'Processing، Processed، Shipped، Complete',
'Oc_G_Default_Cancel' => 'Canceled، Denied، Failed، Refunded، Reversed، Chargeback، Expired، Voided',
'Oc_G_Orders_2' => 'تُملأ القوائم من متجرك عند الاتصال الأول ويمكن تغييرها في تبويب الاتصال. أبقِ القائمة الأولى مطابقة للحالات التي تخصم المخزون في OpenCart، حتى يحرّك الطرفان المخزون في الخطوة نفسها.',
'Oc_G_Orders_3' => 'الطلب الذي يحتوي على بند لا يطابق أي منتج يُعلَّق، ويُستورد المنتج من المتجر إن كان موجودًا هناك. تُعاد محاولة الطلبات المعلقة في كل فحص مجدول؛ وبعد اثنتي عشرة محاولة تُسجَّل وتُترك لتسحبها يدويًا.',
'Oc_G_T_Cancel' => 'الإلغاءات والمبالغ المستردة',
'Oc_G_Cancel_1' => 'عندما يصل الطلب إلى حالة إلغاء في المتجر، تُعكس عملية البيع المقابلة هنا: يعود المخزون، وتُحذف دفعاتها، ويُحذف البيع، تمامًا كما لو حذفته من صفحة المبيعات.',
'Oc_G_Cancel_2' => 'البيع الذي تم تسليمه مسبقًا، أو له مرتجع، أو قبلته جهة ضريبية لا يعكسه المتجر أبدًا. بل يُعلَّم في ملاحظاته وفي السجلات لتراجعه.',
'Oc_G_Cancel_3' => 'إذا أُعيد تفعيل الطلب في المتجر لاحقًا، فإنه يدخل مجددًا كعملية بيع جديدة.',
'Oc_G_T_Automation' => 'مفاتيح الأتمتة',
'Oc_G_Auto_1' => 'استيراد الطلبات تلقائيًا: إشعارات الطلبات والفحص المجدول. عند الإيقاف، لا تصل الطلبات إلا عندما تسحبها من تبويب الطلبات.',
'Oc_G_Auto_2' => 'دفع المخزون تلقائيًا: تحديثات المخزون المباشرة والفحص كل ساعة. عند الإيقاف، لا يتغير المتجر إلا عندما تدفع المخزون يدويًا.',
'Oc_G_Auto_3' => 'دفع تغييرات المنتجات تلقائيًا: المنتج المُنشأ أو المعدَّل هنا يحدِّث المتجر فورًا. عند الإيقاف، استخدم تبويب المنتجات.',
'Oc_G_T_Faq' => 'أسئلة',
'Oc_G_Q_Secret' => 'يفيد اختبار الاتصال بأن المفتاح السري غير مطابق',
'Oc_G_A_Secret' => 'افتح وحدة {company} Connector في OpenCart وانسخ المفتاح السري مجددًا؛ فالوحدة المعاد تثبيتها تحصل على مفتاح جديد. الصقه في تبويب الاتصال واحفظ قبل الاختبار.',
'Oc_G_Q_Clock' => 'يفيد اختبار الاتصال بأن ساعة المتجر بعيدة جدًا عن الوقت الصحيح',
'Oc_G_A_Clock' => 'تحمل الطلبات الموقَّعة الوقت وتُرفض عندما يختلف الوقت بين الساعتين بأكثر من خمس دقائق. اضبط التاريخ والوقت على خادم المتجر.',
'Oc_G_Q_Redirect' => 'يفيد اختبار الاتصال بأن المتجر يعيد التوجيه إلى عنوان آخر',
'Oc_G_A_Redirect' => 'يستجيب متجرك على عنوان مختلف، عادةً https بدلًا من http أو مع www. استخدم العنوان المعروض في الرسالة كرابط المتجر.',
'Oc_G_Q_Not_Answering' => 'يفيد اختبار الاتصال بأن الموصِّل لم يستجب',
'Oc_G_A_Not_Answering' => 'العنوان ليس متجر OpenCart، أو الوحدة غير مثبتة أو معطلة. تحقق من رابط المتجر، ثم من أن {company} Connector يظهر مثبتًا ومفعّلًا ضمن Extensions → Modules.',
'Oc_G_Q_No_Orders' => 'تُقدَّم الطلبات في المتجر لكنها تستغرق دقائق حتى تظهر',
'Oc_G_A_No_Orders' => 'لا يستطيع المتجر الوصول إلى مساحة العمل هذه، لذا لا تصل الطلبات إلا عبر الفحص المجدول. تحقق من عنوان {company} في صفحة الوحدة: يجب أن يكون قابلًا للوصول من خادم المتجر. تشغيل اختبار الاتصال يسجّله مجددًا.',
'Oc_G_Q_Stock_Wrong' => 'كمية في المتجر غير صحيحة',
'Oc_G_A_Stock_Wrong' => 'ادفع المخزون من تبويب المخزون، فهو يعيد كتابة كل منتج مربوط من الأرقام الموجودة هنا. وإذا استمر الانحراف، فتحقق من أن مفتاح المخزون مفعّل وأن لا أحد يعدّل الكميات في OpenCart.',
