'Oc_L_F_Unreachable' => 'افتح رابط المتجر في متصفح للتحقق من أنه متصل، وتأكد من أن وحدة الموصِّل مثبتة ومفعّلة، وتحقق من عدم وجود جدار حماية أو وضع صيانة يحظر خادمنا.',
