'Oc_L_F_Not_Configured' => 'املأ رابط المتجر والمفتاح السري في تبويب الاتصال، واحفظ، وشغّل اختبار الاتصال.',
'Oc_L_H_Model_Taken' => 'منتج مدفوع إلى المتجر له كود يستخدمه منتج آخر في المتجر، أو أحد متغيراته، كموديل له مسبقًا.',
'Oc_L_F_Model_Taken' => 'غيّر الكود في أحد المنتجين، أو اسحب المنتجات أولًا حتى يُربط منتج المتجر الموجود بدلًا من إنشائه مجددًا.',
