'Oc_L_F_Model_Missing' => 'أعطِ المنتج كودًا واسمًا هنا، ثم ادفعه مجددًا.',
'Oc_L_H_Held' => 'استُلم طلب لكن بعض بنوده لا تطابق أي منتج هنا، لذا هو قيد الانتظار ولم تُنشأ أي عملية بيع.',
'Oc_L_F_Held' => 'أنشئ المنتجات الناقصة أو اسحبها (البنود مدرجة أدناه)، ثم اسحب الطلبات مجددًا. تُعاد محاولة الطلبات المعلقة تلقائيًا بضع مرات.',
'Oc_L_H_Given_Up' => 'تعذّر استيراد طلب بعد عدة محاولات ولم تعد تُعاد محاولته.',
'Oc_L_F_Given_Up' => 'تأكد من وجود منتجاته هنا، ثم اسحب الطلبات يدويًا من تبويب الطلبات بتاريخ يسبق الطلب.',
'Oc_L_H_Review' => 'أُلغي طلب في OpenCart بعد تسليم البيع المقابل هنا أو إرجاعه، لذا لم يُعكس المخزون تلقائيًا.',
'Oc_L_F_Review' => 'افتح البيع وقرّر ما إذا كنت ستُرجع البنود أو تتركه كما هو.',
'Oc_L_H_Reversed' => 'أُلغي طلب في OpenCart وعُكس البيع المقابل هنا، فأُعيد مخزونه.',
'Oc_L_H_Backlog' => 'وجد سحب الطلبات المجدول طلبات أكثر مما يعالجه في تشغيل واحد وسيبدأ مجددًا في المرة القادمة.',
'Oc_L_F_Backlog' => 'اسحب الطلبات يدويًا من تبويب الطلبات لتصفية المتراكم.',
'Oc_L_H_Paused' => 'توقفت عمليات الدفع التلقائية مؤقتًا لأن المتجر توقف عن الاستجابة. تُرسل التغييرات التي جرت خلال ذلك بمجرد أن يستجيب مجددًا.',
'Oc_L_F_Paused' => 'تحقق من أن المتجر متصل. لا يلزم شيء آخر؛ تستأنف قائمة الانتظار من تلقاء نفسها.',
'Oc_L_H_Busy' => 'تداخلت عمليتا دفع تلقائيتان فتنحّت إحداهما. لم يُفقد أي شيء.',
'Oc_L_H_Codes_Suffixed' => 'بعض المنتجات المسحوبة تحمل كودًا كان لمنتج آخر من المتجر هنا مسبقًا، عادةً لأن حقل الكود المختار فارغ أو يحتوي على اسم تصنيف. وقد أُنشئت بإلحاق معرّف OpenCart حتى لا يندمج منتجان.',
'Oc_L_F_Codes_Suffixed' => 'املأ حقل الكود (الموديل، SKU، ISBN…) في OpenCart للمنتجات المدرجة أدناه، أو اختر مصدر كود منتج آخر في تبويب الاتصال، ثم أعد تعيين روابط المنتجات واسحب مجددًا.',
'Oc_L_H_Options' => 'بعض منتجات المتجر لها خيارات (المقاس، اللون…) دون مخزون للمتغيرات، لذا يُتتبع المخزون للمنتج ككل.',
'Oc_L_F_Options' => 'لا يلزم شيء. لتتبع المخزون لكل خيار، حوّل تلك الخيارات إلى متغيرات في OpenCart 4، أو استخدم خيارًا واحدًا لكل منتج في OpenCart 3.',
'Oc_L_H_Pull_Ok' => 'قُرئت هذه الصفحة من المنتجات من المتجر. «أُنشئ» يعني منتجًا جديدًا هنا؛ و«حُدِّث» يعني أنه كان موجودًا مسبقًا ورُبط.',
'Oc_L_H_Pull_Failed' => 'تعذّر حفظ بعض المنتجات في هذه الصفحة هنا؛ كل منها مدرج أدناه مع السبب.',
'Oc_L_F_Pull_Failed' => 'أصلح المنتجات المدرجة في OpenCart (السبب المعتاد هو اسم أو كود مفقود) واسحب مجددًا. المنتجات الفاشلة فقط هي المتأثرة.',
'Oc_L_H_Push_Warnings' => 'أُرسلت المنتجات إلى المتجر، لكن المتجر أبلغ عن مشكلات في بعضها، مثل صورة لم يتمكن من تنزيلها.',
'Oc_L_F_Push_Warnings' => 'اقرأ القائمة أدناه. يجب أن تكون الصور قابلة للوصول من خادم المتجر؛ وكل ما عدا ذلك حُفظ كما أُرسل.',
'Oc_L_H_Missing_Remote' => 'دُفع المخزون، لكن بعض المنتجات المربوطة لم تعد موجودة في المتجر.',
'Oc_L_F_Missing_Remote' => 'ادفع المنتجات لإعادة إنشائها في المتجر، أو أعد تعيين روابط المنتجات إذا حُذفت عمدًا.',
'Oc_L_H_Generic' => 'فشلت خطوة مزامنة. الرسالة أعلاه هي السبب الذي أورده المتجر أو الخادم.',
'Oc_L_F_Generic' => 'شغّل اختبار الاتصال في تبويب الاتصال. إذا نجح، فأعد محاولة الخطوة؛ وإذا فشل، فاتبع التلميح الذي يقدمه.',
'Oc_L_H_Code_Fallback' => 'وصلت بعض المنتجات في هذه الصفحة دون قيمة في الحقل المختار كمصدر لكود المنتج، لذا استُخدم الموديل (غالبًا اسم تصنيف) ككود لها.',
'Oc_L_F_Code_Fallback' => 'راجع "المنتجات التي تحمل كل حقل" أدناه. إذا أظهر الحقل المختار 0 بينما يحتوي المتجر فعلًا على تلك القيم، فإن المتجر يحفظها تحت اسم معرّف مختلف؛ افتح أحد المنتجات المدرجة في OpenCart (تبويب Data، Product Codes) وأرسل إلينا ما يظهر. وإلا فاملأ الحقل في OpenCart للمنتجات المدرجة واسحب مجددًا.',
'Oc_L_H_Old_Connector' => 'لا يزال المتجر يشغّل موصِّلًا أقدم من 1.1.0، يرسل الموديل و SKU فقط، لذا لا يصل حقل الكود المختار أبدًا واستُخدم الموديل.',
'Oc_L_F_Old_Connector' => 'نزّل الموصِّل مجددًا، وألغِ تثبيت القديم واحذفه في OpenCart (Extensions → Installer)، وثبّت الجديد، والصق مفتاحه السري الجديد في تبويب الاتصال وشغّل اختبار الاتصال. يجب أن تُظهر الصفحة Connector 1.1.0 قبل أن تسحب.',
